PathwayData.put("data/reading_writing/units/L01U3.json",{"strand":"reading_writing","level":1,"cefr":"A1a","unit":3,"theme":"My School Day","essential_question":"What do we do at school, and why?","schema_version":"1.0","core_words":["teacher","classroom","book","pen","pencil","bag","desk","board","read","write","draw","listen","lunch","playground"],"recycled_words":["friend","happy","favorite","like","morning","breakfast","table","open","ready","busy","door","window"],"rubrics":[{"id":"RW-RUBRIC-5T","title":"Analytic writing rubric","traits":[{"name":"Ideas","name_ar":"الأفكار","bands":[{"score":4,"descriptor":"My ideas are clear, interesting and fully developed with strong details.","descriptor_ar":"أفكاري واضحة وممتعة ومدعومة بتفاصيل قوية."},{"score":3,"descriptor":"My ideas are clear and have enough details.","descriptor_ar":"أفكاري واضحة ومعها تفاصيل كافية."},{"score":2,"descriptor":"My main idea is there but needs more details.","descriptor_ar":"فكرتي الرئيسية موجودة لكنها تحتاج إلى تفاصيل أكثر."},{"score":1,"descriptor":"My ideas are unclear or very few.","descriptor_ar":"أفكاري غير واضحة أو قليلة جدًا."}]},{"name":"Organization","name_ar":"التنظيم","bands":[{"score":4,"descriptor":"Clear beginning, middle and end; ideas flow with linking words.","descriptor_ar":"بداية ووسط ونهاية واضحة، والأفكار مترابطة بكلمات الربط."},{"score":3,"descriptor":"Clear order with some linking words.","descriptor_ar":"ترتيب واضح مع بعض كلمات الربط."},{"score":2,"descriptor":"Some order, but parts are mixed up.","descriptor_ar":"يوجد بعض الترتيب لكن بعض الأجزاء غير مرتبة."},{"score":1,"descriptor":"Ideas are not in order.","descriptor_ar":"الأفكار غير مرتبة."}]},{"name":"Vocabulary","name_ar":"المفردات","bands":[{"score":4,"descriptor":"I use exact, varied words, including new unit words, correctly.","descriptor_ar":"أستخدم كلمات دقيقة ومتنوعة، منها كلمات الوحدة الجديدة، بشكل صحيح."},{"score":3,"descriptor":"I use some new words correctly.","descriptor_ar":"أستخدم بعض الكلمات الجديدة بشكل صحيح."},{"score":2,"descriptor":"I use simple words; some are repeated or wrong.","descriptor_ar":"أستخدم كلمات بسيطة، وبعضها مكرر أو غير صحيح."},{"score":1,"descriptor":"I use very few words; the meaning is hard to understand.","descriptor_ar":"أستخدم كلمات قليلة جدًا ويصعب فهم المعنى."}]},{"name":"Sentence fluency","name_ar":"سلاسة الجمل","bands":[{"score":4,"descriptor":"My sentences are complete, varied in length and easy to read aloud.","descriptor_ar":"جملي كاملة ومتنوعة الطول وسهلة القراءة بصوت عالٍ."},{"score":3,"descriptor":"Most sentences are complete, with some variety.","descriptor_ar":"معظم جملي كاملة مع بعض التنويع."},{"score":2,"descriptor":"Many sentences are short or start the same way.","descriptor_ar":"كثير من جملي قصيرة أو تبدأ بالطريقة نفسها."},{"score":1,"descriptor":"Sentences are incomplete or run together.","descriptor_ar":"جملي ناقصة أو متداخلة."}]},{"name":"Conventions","name_ar":"قواعد الكتابة","bands":[{"score":4,"descriptor":"Capitals, punctuation, spelling and grammar are almost always correct.","descriptor_ar":"الحروف الكبيرة وعلامات الترقيم والإملاء والقواعد صحيحة دائمًا تقريبًا."},{"score":3,"descriptor":"A few mistakes that do not affect meaning.","descriptor_ar":"أخطاء قليلة لا تؤثر في المعنى."},{"score":2,"descriptor":"Several mistakes; the meaning is sometimes unclear.","descriptor_ar":"عدة أخطاء، والمعنى أحيانًا غير واضح."},{"score":1,"descriptor":"Many mistakes make it hard to read.","descriptor_ar":"أخطاء كثيرة تجعل القراءة صعبة."}]}]}],"lessons":[{"id":"RW-L01-U3-LS1","title":"Word Power: My School Day","lesson_type":"vocabulary","objectives":["read and say 14 school words and 2 Tier 2 words (learn, start)","use picture cues and actions to understand action words (read, write, draw, listen)","use school words and action words in short sentences about their school day"],"objectives_ar":["قراءة ونطق 14 كلمة عن المدرسة وكلمتين أكاديميتين (learn, start).","استخدام الصور والحركات لفهم كلمات الأفعال.","استخدام كلمات المدرسة والأفعال في جمل قصيرة عن يومهم الدراسي."],"success_criteria":["I can read and say the school words.","I can show and say an action word.","I can say what I do at school."],"success_criteria_ar":["أستطيع قراءة كلمات المدرسة ونطقها.","أستطيع تمثيل كلمة الفعل وقولها.","أستطيع قول ما أفعله في المدرسة."],"map_area":"Vocabulary: Acquisition and Use","vocabulary":[{"word":"teacher","pos":"noun","ipa":"/ˈtitʃər/","definition":"a person who helps you learn at school","arabic":"معلم / معلمة","example":"Our teacher is kind.","image_id":"IMG-RW-L01-U3-LS1-V01","audio_id":"AUD-RW-L01-U3-LS1-V01","tier":"core"},{"word":"classroom","pos":"noun","ipa":"/ˈklæsˌrum/","definition":"the room where a class learns","arabic":"فصل دراسي","example":"Our classroom has big windows.","image_id":"IMG-RW-L01-U3-LS1-V02","audio_id":"AUD-RW-L01-U3-LS1-V02","tier":"core"},{"word":"book","pos":"noun","ipa":"/bʊk/","definition":"pages with words and pictures to read","arabic":"كتاب","example":"This book has a red cover.","image_id":"IMG-RW-L01-U3-LS1-V03","audio_id":"AUD-RW-L01-U3-LS1-V03","tier":"core"},{"word":"pen","pos":"noun","ipa":"/pɛn/","definition":"you write with ink using it","arabic":"قلم حبر","example":"My pen is blue.","image_id":"IMG-RW-L01-U3-LS1-V04","audio_id":"AUD-RW-L01-U3-LS1-V04","tier":"core"},{"word":"pencil","pos":"noun","ipa":"/ˈpɛnsəl/","definition":"you write with it and can rub out mistakes","arabic":"قلم رصاص","example":"Sharpen your pencil.","image_id":"IMG-RW-L01-U3-LS1-V05","audio_id":"AUD-RW-L01-U3-LS1-V05","tier":"core"},{"word":"bag","pos":"noun","ipa":"/bæɡ/","definition":"you carry your books in it","arabic":"حقيبة","example":"My bag is heavy.","image_id":"IMG-RW-L01-U3-LS1-V06","audio_id":"AUD-RW-L01-U3-LS1-V06","tier":"core"},{"word":"desk","pos":"noun","ipa":"/dɛsk/","definition":"a table where a student sits and works","arabic":"مكتب / طاولة الطالب","example":"Put your book on your desk.","image_id":"IMG-RW-L01-U3-LS1-V07","audio_id":"AUD-RW-L01-U3-LS1-V07","tier":"core"},{"word":"board","pos":"noun","ipa":"/bɔrd/","definition":"the big flat surface at the front where the teacher writes","arabic":"سبورة","example":"Look at the board.","image_id":"IMG-RW-L01-U3-LS1-V08","audio_id":"AUD-RW-L01-U3-LS1-V08","tier":"core"},{"word":"read","pos":"verb","ipa":"/rid/","definition":"to look at words and understand them","arabic":"يقرأ","example":"We read a story every day.","image_id":"IMG-RW-L01-U3-LS1-V09","audio_id":"AUD-RW-L01-U3-LS1-V09","tier":"core"},{"word":"write","pos":"verb","ipa":"/raɪt/","definition":"to make letters and words with a pen or pencil","arabic":"يكتب","example":"Write the date, please.","image_id":"IMG-RW-L01-U3-LS1-V10","audio_id":"AUD-RW-L01-U3-LS1-V10","tier":"core"},{"word":"draw","pos":"verb","ipa":"/drɔ/","definition":"to make a picture with a pencil or crayon","arabic":"يرسم","example":"Layla draws a palm tree.","image_id":"IMG-RW-L01-U3-LS1-V11","audio_id":"AUD-RW-L01-U3-LS1-V11","tier":"core"},{"word":"listen","pos":"verb","ipa":"/ˈlɪsən/","definition":"to pay attention to sounds or words","arabic":"يستمع / يُصغي","example":"Listen to the teacher.","image_id":"IMG-RW-L01-U3-LS1-V12","audio_id":"AUD-RW-L01-U3-LS1-V12","tier":"core"},{"word":"lunch","pos":"noun","ipa":"/lʌntʃ/","definition":"the meal in the middle of the day","arabic":"الغداء / وجبة منتصف اليوم","example":"We eat lunch at twelve.","image_id":"IMG-RW-L01-U3-LS1-V13","audio_id":"AUD-RW-L01-U3-LS1-V13","tier":"core"},{"word":"playground","pos":"noun","ipa":"/ˈpleɪˌɡraʊnd/","definition":"an outside place at school for playing","arabic":"ساحة اللعب","example":"We run in the playground.","image_id":"IMG-RW-L01-U3-LS1-V14","audio_id":"AUD-RW-L01-U3-LS1-V14","tier":"core"},{"word":"learn","pos":"verb","ipa":"/lɝn/","definition":"to get new knowledge or a new skill","arabic":"يتعلّم","example":"We learn new words today.","image_id":"IMG-RW-L01-U3-LS1-V15","audio_id":"AUD-RW-L01-U3-LS1-V15","tier":"tier2"},{"word":"start","pos":"verb","ipa":"/stɑrt/","definition":"to begin","arabic":"يبدأ","example":"School starts at seven.","image_id":"IMG-RW-L01-U3-LS1-V16","audio_id":"AUD-RW-L01-U3-LS1-V16","tier":"tier2"}],"explanation":{"text":"An **action word** tells what someone **does**: *read, write, draw, listen*. (Later you will call it a **verb**.)\n\nA **picture cue** helps you: look at what the person in the picture is doing. Then find the action word.\n\nShow the action with your body, say the word, and use it: **I read. We listen.**","examples":["Picture: a boy with an open book → **read** → I read a book.","Picture: a hand with a pencil on paper → **write** → I write my name.","Picture: a girl with crayons and a picture of a tree → **draw** → She draws a tree.","Picture: a child with a hand behind the ear → **listen** → We listen to the teacher.","Picture: children running outside → **play** → We play in the playground.","Picture: a child eating a sandwich → **eat** → I eat lunch.","Picture: a teacher pointing at the board → **look** → Look at the board.","Picture: a child holding up a new word card → **learn** → We learn new words.","Picture: a bell ringing and children going in → **start** → School starts at seven."],"common_errors":["✗ I am read a book. → ✓ I read a book. (Do not put **am** before an action word here.)","✗ Listen the teacher. → ✓ Listen to the teacher. (Say **listen to**.)","✗ I write by pencil. → ✓ I write with a pencil. (Use **with**.)","✗ He draw a cat. → ✓ He draws a cat. (With he/she, add **-s**.)","✗ I learn the English. → ✓ I learn English. (No *the* before languages.)","✗ We eat the lunch at twelve. → ✓ We eat lunch at twelve. (No *the* before meals here.)","✗ The class start at seven. → ✓ The class starts at seven. (One class → **starts**.)"],"arabic":"كلمة الفعل (action word) تخبرنا بما يفعله الشخص مثل: read, write, draw, listen، وستتعلم لاحقًا أن اسمها verb.\n\nالصورة تساعدك: انظر إلى ما يفعله الشخص في الصورة، ثم ابحث عن كلمة الفعل.\n\nمثّل الفعل بجسمك وقل الكلمة واستخدمها في جملة: I read. We listen.\n\nانتبه: لا نقول I am read بل I read، ونقول listen to the teacher."},"video":{"script":[{"time":"00:00–00:15","narration":"Welcome to Mr. Khalid's classroom! What do we do at school?","on_screen":"My School Day","visual":"The classroom door opens; Mr. Khalid waves; students sit at desks."},{"time":"00:15–00:50","narration":"Look! Sami reads a book. Read! Now you: read!","on_screen":"read 📖","visual":"Sami opens a book; the word 'read' bounces; a small icon of hands holding a book appears."},{"time":"00:50–01:20","narration":"Noura writes with a pencil. Write! Layla draws a tree. Draw!","on_screen":"write ✏️ · draw 🎨","visual":"Close-ups of hands writing and drawing; the action words pop up."},{"time":"01:20–01:45","narration":"Everyone listens to Mr. Khalid. Listen!","on_screen":"listen 👂","visual":"Students put a hand to the ear; sound waves come from the teacher."},{"time":"01:45–02:10","narration":"At twelve, we eat lunch. Then we play in the playground!","on_screen":"lunch · playground","visual":"A clock shows 12; lunch boxes open; children run outside to the playground."},{"time":"02:10–02:30","narration":"Look at the picture, find the action, say the word!","on_screen":"Look · Do · Say","visual":"Saqr mimes reading, writing and listening while the words light up."}],"captions_ar":["مرحبًا بكم في فصل الأستاذ خالد! ماذا نفعل في المدرسة؟","انظروا! سامي يقرأ كتابًا. اقرأ! والآن أنت: اقرأ!","نورة تكتب بقلم الرصاص. اكتب! ليلى ترسم شجرة. ارسم!","الجميع يستمع إلى الأستاذ خالد. استمع!","في الساعة الثانية عشرة نتناول الغداء، ثم نلعب في ساحة اللعب!","انظر إلى الصورة، وابحث عن الفعل، وقل الكلمة!"],"voice":"Narrator: American English, warm female teacher, speed 0.8. Mr. Khalid: calm, friendly male teacher voice. Leave 2-second pauses for children to do the action."},"texts":[],"activities":[{"id":"RW-L01-U3-LS1-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Look at the picture clue. Choose the word.","instructions_ar":"انظر إلى دليل الصورة واختر الكلمة.","items":[{"q":"Picture: a child holding a crayon and making a picture of a cat. What does the child do?","answer":"draw","explanation":"Making a picture = draw.","explanation_ar":"عمل صورة يعني يرسم.","options":["listen","read","draw","eat"],"dok":1,"skill":"action words","stage":"controlled"},{"q":"Picture: a child with a hand behind the ear. What does the child do?","answer":"listen","explanation":"A hand at the ear shows listening.","explanation_ar":"اليد عند الأذن تعني الاستماع.","options":["write","listen","draw","play"],"dok":1,"skill":"action words","stage":"controlled"},{"q":"The teacher writes on the ___.","answer":"board","explanation":"Teachers write on the board.","explanation_ar":"المعلم يكتب على السبورة.","options":["board","lunch","bag","playground"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"You can rub out mistakes when you write with a ___.","answer":"pencil","explanation":"A pencil has an eraser.","explanation_ar":"قلم الرصاص يمكن مسحه.","options":["pen","desk","pencil","book"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"We run and play outside in the ___.","answer":"playground","explanation":"The playground is outside.","explanation_ar":"ساحة اللعب في الخارج.","options":["classroom","playground","desk","bag"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"I carry my books in my ___.","answer":"bag","explanation":"A bag carries books.","explanation_ar":"الحقيبة تحمل الكتب.","options":["board","lunch","desk","bag"],"dok":1,"skill":"vocabulary","stage":"controlled"}]},{"id":"RW-L01-U3-LS1-A2","type":"gap_fill","stage":"guided","instructions":"Guided practice: Use the word bank to complete each sentence.","instructions_ar":"استخدم بنك الكلمات لإكمال الجمل.","items":[{"q":"Our ________ is Mr. Khalid.","answer":"teacher","explanation":"Mr. Khalid is a teacher.","explanation_ar":"الأستاذ خالد معلم.","stage":"guided"},{"q":"I sit at my ________ and open my book.","answer":"desk","explanation":"Students sit at a desk.","explanation_ar":"يجلس الطالب إلى طاولته.","stage":"guided"},{"q":"We eat ________ at twelve o'clock.","answer":"lunch","explanation":"Lunch is the middle meal.","explanation_ar":"الغداء وجبة منتصف اليوم.","stage":"guided"},{"q":"School ________ at seven in the morning.","answer":"starts","explanation":"Start = begin; one thing → starts.","explanation_ar":"تبدأ المدرسة.","stage":"guided"},{"q":"At school, we ________ new things every day.","answer":"learn","explanation":"Learn = get new knowledge.","explanation_ar":"نتعلم أشياء جديدة.","stage":"guided"},{"q":"There are 24 desks in our ________.","answer":"classroom","explanation":"Desks are in the classroom.","explanation_ar":"الطاولات في الفصل.","stage":"guided"}]},{"id":"RW-L01-U3-LS1-A3","type":"open","stage":"freer","instructions":"Freer practice: Write the action word for each school thing.","instructions_ar":"اكتب فعلًا مناسبًا لكل أداة مدرسية.","items":[{"q":"book → I ______ a book.","answer":"read","explanation":"We read books.","explanation_ar":"نقرأ الكتب.","dok":1,"skill":"action words","stage":"freer"},{"q":"pencil → I ______ with a pencil.","answer":"write","explanation":"We write with pencils.","explanation_ar":"نكتب بقلم الرصاص.","dok":1,"skill":"action words","stage":"freer"},{"q":"crayons → I ______ a picture.","answer":"draw","explanation":"We draw with crayons.","explanation_ar":"نرسم بالألوان.","dok":1,"skill":"action words","stage":"freer"},{"q":"the teacher's voice → I ______ to the teacher.","answer":"listen","explanation":"We listen to voices.","explanation_ar":"نستمع إلى الأصوات.","dok":1,"skill":"action words","stage":"freer"}]},{"id":"RW-L01-U3-LS1-A4","type":"open","stage":"production","instructions":"Writing: Write about YOUR school. Use the new words.","instructions_ar":"اكتب عن مدرستك مستخدمًا الكلمات الجديدة.","items":[{"q":"What is your teacher's name? Write a sentence.","answer":"My teacher is Mr. Fahad.","explanation":"My teacher is + name.","explanation_ar":"My teacher is + الاسم.","dok":1,"skill":"personal writing","stage":"production"},{"q":"What do you like to do at school? Use an action word.","answer":"I like to draw.","explanation":"I like to + action word.","explanation_ar":"I like to + فعل.","dok":2,"skill":"personal writing","stage":"production"},{"q":"Where do you play at school?","answer":"I play in the playground.","explanation":"A place word.","explanation_ar":"كلمة مكان.","dok":1,"skill":"personal writing","stage":"production"},{"q":"What is in your bag? Write three things.","answer":"a book, a pen and a lunch box","explanation":"Three school things.","explanation_ar":"ثلاثة أشياء مدرسية.","dok":1,"skill":"vocabulary","stage":"production"}]}],"game":{"name":"Action Charades Relay","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Watch-and-tap: a cartoon student does an action; the child taps the right word from four. Each correct answer adds a block to a school building; finish the building in 12 answers.","Two teams line up.","The first player in Team A takes a card and acts it out (no talking).","Team A has 15 seconds to say the word and a sentence (\"Draw! I draw a cat.\").","Correct word = 1 point; correct sentence = 1 bonus point.","Teams take turns; play until all cards are used."],"data":[]},"exit_quiz":[{"q":"Which word is an action word?","answer":"write","explanation":"Write tells what we do.","explanation_ar":"write فعل.","options":["desk","write","board","lunch"],"dok":1,"skill":"action words"},{"q":"Which is a school thing, not an action?","answer":"pencil","explanation":"A pencil is a thing.","explanation_ar":"قلم الرصاص شيء.","options":["draw","pencil","listen","read"],"dok":1,"skill":"vocabulary"},{"q":"We eat in the middle of the day. We eat ___.","answer":"lunch","explanation":"The middle meal is lunch.","explanation_ar":"وجبة منتصف اليوم الغداء.","options":["lunch","board","desk","pen"],"dok":1,"skill":"vocabulary"},{"q":"A person who helps you learn at school is a ___.","answer":"teacher","explanation":"A teacher helps you learn.","explanation_ar":"المعلم يساعدك على التعلم.","options":["teacher","playground","bag","classroom"],"dok":1,"skill":"vocabulary"},{"q":"Picture: a boy looking at the words in a book. The boy ___.","answer":"reads","explanation":"Looking at words = reading.","explanation_ar":"النظر إلى الكلمات قراءة.","options":["draws","listens","eats","reads"],"dok":1,"skill":"picture cue"},{"q":"Which sentence uses *listen* correctly?","answer":"We listen to the teacher.","explanation":"Say *listen to*.","explanation_ar":"نقول listen to.","options":["We listen the teacher.","We are listen teacher.","We listen to the teacher.","We listening the teacher."],"dok":2,"skill":"usage"},{"q":"*School starts at seven.* *Starts* means ___.","answer":"begins","explanation":"Start = begin.","explanation_ar":"start تعني يبدأ.","options":["ends","sleeps","runs","begins"],"dok":2,"skill":"vocabulary"},{"q":"Which is NOT in a classroom?","answer":"a palm tree in the desert","explanation":"A desert palm tree is not in a classroom.","explanation_ar":"النخلة في الصحراء ليست في الفصل.","options":["a palm tree in the desert","a desk","a board","a book"],"dok":2,"skill":"categories"},{"q":"Noura makes a picture of the sea with crayons. Which sentence tells this?","answer":"Noura draws the sea.","explanation":"Making a picture = draw.","explanation_ar":"ترسم البحر.","options":["Noura reads the sea.","Noura listens to the sea.","Noura eats the sea.","Noura draws the sea."],"dok":2,"skill":"action words"},{"q":"Why do we go to school?","answer":"to learn new things","explanation":"School is a place to learn.","explanation_ar":"نذهب إلى المدرسة لنتعلم.","options":["to sleep all day","to cook lunch","to learn new things","to buy toys"],"dok":3,"skill":"essential question"}],"images":[{"id":"IMG-RW-L01-U3-LS1-V01","prompt":"Picture for the word 'teacher': Mr. Khalid smiling in front of a class"},{"id":"IMG-RW-L01-U3-LS1-V02","prompt":"Picture for the word 'classroom': a bright classroom with desks in groups of four"},{"id":"IMG-RW-L01-U3-LS1-V03","prompt":"Picture for the word 'book': a picture book with a red cover"},{"id":"IMG-RW-L01-U3-LS1-V04","prompt":"Picture for the word 'pen': a blue pen"},{"id":"IMG-RW-L01-U3-LS1-V05","prompt":"Picture for the word 'pencil': a yellow pencil with an eraser"},{"id":"IMG-RW-L01-U3-LS1-V06","prompt":"Picture for the word 'bag': a navy school backpack"},{"id":"IMG-RW-L01-U3-LS1-V07","prompt":"Picture for the word 'desk': a school desk with a book on it"},{"id":"IMG-RW-L01-U3-LS1-V08","prompt":"Picture for the word 'board': a white board with a drawing of the sun"},{"id":"IMG-RW-L01-U3-LS1-V09","prompt":"Picture for the word 'read': a boy reading a book on a beanbag"},{"id":"IMG-RW-L01-U3-LS1-V10","prompt":"Picture for the word 'write': a hand writing letters on lined paper"},{"id":"IMG-RW-L01-U3-LS1-V11","prompt":"Picture for the word 'draw': a girl drawing a palm tree with crayons"},{"id":"IMG-RW-L01-U3-LS1-V12","prompt":"Picture for the word 'listen': a child with a hand cupped to the ear"},{"id":"IMG-RW-L01-U3-LS1-V13","prompt":"Picture for the word 'lunch': a lunch box with a sandwich and an apple"},{"id":"IMG-RW-L01-U3-LS1-V14","prompt":"Picture for the word 'playground': a school playground with a slide and shade trees"},{"id":"IMG-RW-L01-U3-LS1-V15","prompt":"Picture for the word 'learn': a child with a light bulb above the head and a book"},{"id":"IMG-RW-L01-U3-LS1-V16","prompt":"Picture for the word 'start': a race starting line with children ready"},{"id":"IMG-RW-L01-U3-LS1-01","prompt":"Mr. Khalid's classroom with students reading, writing, drawing and listening."},{"id":"IMG-RW-L01-U3-LS1-02","prompt":"Four pictures showing read, write, draw and listen."},{"id":"IMG-RW-L01-U3-LS1-03","prompt":"A school building with children walking in."}],"audio":[{"id":"AUD-RW-L01-U3-LS1-V01","script":"teacher. Our teacher is kind."},{"id":"AUD-RW-L01-U3-LS1-V02","script":"classroom. Our classroom has big windows."},{"id":"AUD-RW-L01-U3-LS1-V03","script":"book. This book has a red cover."},{"id":"AUD-RW-L01-U3-LS1-V04","script":"pen. My pen is blue."},{"id":"AUD-RW-L01-U3-LS1-V05","script":"pencil. Sharpen your pencil."},{"id":"AUD-RW-L01-U3-LS1-V06","script":"bag. My bag is heavy."},{"id":"AUD-RW-L01-U3-LS1-V07","script":"desk. Put your book on your desk."},{"id":"AUD-RW-L01-U3-LS1-V08","script":"board. Look at the board."},{"id":"AUD-RW-L01-U3-LS1-V09","script":"read. We read a story every day."},{"id":"AUD-RW-L01-U3-LS1-V10","script":"write. Write the date, please."},{"id":"AUD-RW-L01-U3-LS1-V11","script":"draw. Layla draws a palm tree."},{"id":"AUD-RW-L01-U3-LS1-V12","script":"listen. Listen to the teacher."},{"id":"AUD-RW-L01-U3-LS1-V13","script":"lunch. We eat lunch at twelve."},{"id":"AUD-RW-L01-U3-LS1-V14","script":"playground. We run in the playground."},{"id":"AUD-RW-L01-U3-LS1-V15","script":"learn. We learn new words today."},{"id":"AUD-RW-L01-U3-LS1-V16","script":"start. School starts at seven."},{"id":"AUD-RW-L01-U3-LS1-VID","script":"Welcome to Mr. Khalid's classroom! What do we do at school? Look! Sami reads a book. Read! Now you: read! Noura writes with a pencil. Write! Layla draws a tree. Draw! Everyone listens to Mr. Khalid. Listen! At twelve, we eat lunch. Then we play in the playground! Look at the picture, find the action, say the word!"}]},{"id":"RW-L01-U3-LS2","title":"A Day at Sami's School","lesson_type":"close_reading","objectives":["read a short school story (about 80 words) and answer who, what, where and when questions","make a 'mind movie' (visualize) of each part of the story and draw one part","give an opinion about the best part of Sami's day with a reason"],"objectives_ar":["قراءة قصة مدرسية قصيرة (نحو 80 كلمة) والإجابة عن أسئلة من وماذا وأين ومتى.","تكوين صورة ذهنية لكل جزء من القصة ورسم جزء منها.","إبداء الرأي في أفضل جزء من يوم سامي مع ذكر السبب."],"success_criteria":["I can read the story about Sami's school day.","I can make a picture in my mind and draw it.","I can say my favorite part and why."],"success_criteria_ar":["أستطيع قراءة القصة عن يوم سامي في المدرسة.","أستطيع تكوين صورة في ذهني ورسمها.","أستطيع قول الجزء المفضل لدي ولماذا."],"map_area":"Literary Text: Key Ideas and Details","vocabulary":[{"word":"Sunday","pos":"noun","ipa":"/ˈsʌndeɪ/","definition":"the first school day of the week in Saudi Arabia","arabic":"الأحد","example":"We go back to school on Sunday.","image_id":"IMG-RW-L01-U3-LS2-V01","audio_id":"AUD-RW-L01-U3-LS2-V01","tier":"core"},{"word":"walk","pos":"verb","ipa":"/wɔk/","definition":"to move on your feet, not fast","arabic":"يمشي","example":"I walk to the mosque.","image_id":"IMG-RW-L01-U3-LS2-V02","audio_id":"AUD-RW-L01-U3-LS2-V02","tier":"core"},{"word":"notebook","pos":"noun","ipa":"/ˈnoʊtˌbʊk/","definition":"a book with empty pages for writing","arabic":"دفتر","example":"Write it in your notebook.","image_id":"IMG-RW-L01-U3-LS2-V03","audio_id":"AUD-RW-L01-U3-LS2-V03","tier":"core"},{"word":"together","pos":"adverb","ipa":"/təˈɡɛðər/","definition":"with each other","arabic":"معًا","example":"We eat together.","image_id":"IMG-RW-L01-U3-LS2-V04","audio_id":"AUD-RW-L01-U3-LS2-V04","tier":"core"},{"word":"part","pos":"noun","ipa":"/pɑrt/","definition":"one piece of something","arabic":"جزء","example":"This is my favorite part of the story.","image_id":"IMG-RW-L01-U3-LS2-V05","audio_id":"AUD-RW-L01-U3-LS2-V05","tier":"core"},{"word":"time","pos":"noun","ipa":"/taɪm/","definition":"what a clock shows","arabic":"وقت","example":"It is time for lunch.","image_id":"IMG-RW-L01-U3-LS2-V06","audio_id":"AUD-RW-L01-U3-LS2-V06","tier":"core"},{"word":"good morning","pos":"phrase","ipa":"/ɡʊd ˈmɔrnɪŋ/","definition":"a greeting before noon","arabic":"صباح الخير","example":"Good morning, class!","image_id":"IMG-RW-L01-U3-LS2-V07","audio_id":"AUD-RW-L01-U3-LS2-V07","tier":"core"}],"explanation":{"text":"Good readers make a **mind movie**. As you read, close your eyes and **see** the story in your head.\n\nUse the words to add details: **Who** is there? **Where** are they? **What** do they do? **What can you see and hear?**\n\nAfter reading, **draw** one part of your mind movie and tell a partner about it.","examples":["*Sami walks into his classroom.* → I see a boy with a bag at the classroom door.","*\"Good morning, Mr. Khalid!\"* → I hear Sami's happy voice.","*The class reads a book about the moon.* → I see a book with a big white moon.","*Sami writes with his new pencil.* → I see a yellow pencil and a notebook.","*Sami and Omar eat together.* → I see two friends with lunch boxes.","*They play in the playground.* → I hear children laughing outside.","*Sami draws the moon.* → I see a crayon moon on white paper.","When? *It is Sunday morning.* → I see the morning sun at school.","Me: My favorite part is lunch because I like to eat with my friends."],"common_errors":["✗ Sami walk to his class. → ✓ Sami walks into his classroom. (One person → **walks**.)","✗ They eats together. → ✓ They eat together. (With *they*, no **-s**.)","✗ He says good morning to Mr. Khalid. (no capitals) → ✓ He says, \"Good morning, Mr. Khalid!\" (Greeting words start with a capital inside quotation marks.)","✗ In Sunday → ✓ On Sunday (Use **on** with days.)","✗ My favorite part is lunch because eat with friends. → ✓ My favorite part is lunch because I eat with my friends. (After **because**, use a full sentence.)","✗ Sami draw moon. → ✓ Sami draws the moon. (Add **-s** and **the**.)"],"arabic":"القارئ الجيد يكوّن \"فيلمًا ذهنيًا\": أثناء القراءة أغمض عينيك وتخيّل القصة في رأسك.\n\nاستخدم كلمات النص لإضافة التفاصيل: مَن هناك؟ أين هم؟ ماذا يفعلون؟ ماذا ترى وتسمع؟\n\nبعد القراءة ارسم جزءًا من فيلمك الذهني واحكِ عنه لزميلك.\n\nانتبه: نقول On Sunday مع الأيام، ونقول Sami walks بإضافة s."},"video":{"script":[{"time":"00:00–00:20","narration":"Close your eyes. Make a movie in your mind!","on_screen":"Mind movie 🎬🧠","visual":"A film reel spins inside a cartoon head; Saqr holds a popcorn box."},{"time":"00:20–01:20","narration":"It is Sunday morning. Sami walks into his classroom… First, the class reads a book about the moon…","on_screen":"(story text, part by part)","visual":"The story is read; each part appears first as a blurry sketch, then becomes a clear picture."},{"time":"01:20–01:45","narration":"What can you see? A boy, a bag, a classroom door. What can you hear? \"Good morning!\"","on_screen":"See 👀 · Hear 👂","visual":"Eye and ear icons; the picture zooms in on details."},{"time":"01:45–02:15","narration":"First, next, then, last. Each part is a new scene in your mind movie.","on_screen":"Scene 1 · 2 · 3 · 4","visual":"Four film frames slide across: reading, writing, lunch and play, drawing."},{"time":"02:15–02:40","narration":"Now open your eyes. Draw your favorite part and tell a friend why!","on_screen":"Draw your favorite part!","visual":"Sami holds up his moon drawing; Omar holds up a football drawing."}],"captions_ar":["أغمض عينيك واصنع فيلمًا في ذهنك!","إنه صباح الأحد. يدخل سامي إلى فصله… أولًا يقرأ الفصل كتابًا عن القمر…","ماذا ترى؟ ولدًا وحقيبة وباب الفصل. ماذا تسمع؟ صباح الخير!","أولًا، ثم، بعد ذلك، أخيرًا: كل جزء مشهد جديد في فيلمك الذهني.","افتح عينيك الآن، وارسم الجزء الذي تحبه وأخبر صديقك لماذا!"],"voice":"Narrator: American English, warm female teacher, speed 0.8, calm and dreamy for the 'mind movie' parts. Sami: cheerful boy voice."},"texts":[{"type":"reading","title":"A Day at Sami's School","body":"It is Sunday morning. Sami walks into his classroom. \"Good morning, Mr. Khalid!\" he says.\n\nFirst, the class reads a book about the moon. Sami likes it!\n\nNext, they write in their notebooks. Sami writes with his new pencil.\n\nThen, it is time for lunch. Sami and Omar eat together. After lunch, they play in the playground.\n\nLast, Mr. Khalid says, \"Listen, please. Draw your favorite part of the day.\" Sami draws the moon. What a happy day!","word_count":78,"audio_id":"AUD-RW-L01-U3-LS2-T1","id":"TXT-RW-L01-U3-LS2-1","genre":"narrative","role":"main","difficulty":"BR–200L","glossary":[{"word":"notebook","definition":"a book with empty pages for writing","arabic":"دفتر"},{"word":"part of the day","definition":"one time in the day","arabic":"جزء من اليوم"}]}],"activities":[{"id":"RW-L01-U3-LS2-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read the story. Choose the answer.","instructions_ar":"اقرأ القصة واختر الإجابة.","items":[{"q":"What day is it in the story?","answer":"Sunday","explanation":"Text: It is Sunday morning.","explanation_ar":"إنه يوم الأحد.","options":["Friday","Monday","Saturday","Sunday"],"dok":1,"skill":"key details: when","stage":"controlled"},{"q":"Who is Sami's teacher?","answer":"Mr. Khalid","explanation":"Text: Good morning, Mr. Khalid!","explanation_ar":"المعلم الأستاذ خالد.","options":["Mr. Fahad","Grandpa Saleh","Omar","Mr. Khalid"],"dok":1,"skill":"key details: who","stage":"controlled"},{"q":"What is the class book about?","answer":"the moon","explanation":"Text: a book about the moon.","explanation_ar":"الكتاب عن القمر.","options":["the moon","camels","the sea","football"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What does Sami write with?","answer":"his new pencil","explanation":"Text: with his new pencil.","explanation_ar":"يكتب بقلم رصاص جديد.","options":["his new pencil","a red pen","a crayon","a brush"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Who eats lunch with Sami?","answer":"Omar","explanation":"Text: Sami and Omar eat together.","explanation_ar":"يأكل مع عمر.","options":["Noura","Mr. Khalid","Omar","Adam"],"dok":1,"skill":"key details: who","stage":"controlled"},{"q":"Where do they play after lunch?","answer":"in the playground","explanation":"Text: in the playground.","explanation_ar":"في ساحة اللعب.","options":["in the classroom","in the playground","at home","in the kitchen"],"dok":1,"skill":"key details: where","stage":"controlled"}]},{"id":"RW-L01-U3-LS2-A2","type":"true_false","stage":"guided","instructions":"Guided practice: True or false? Circle one.","instructions_ar":"صح أم خطأ؟ ضع دائرة.","items":[{"q":"Sami says, \"Good night\" to his teacher.","answer":"false","explanation":"He says \"Good morning\".","explanation_ar":"يقول صباح الخير.","options":["true","false"],"stage":"guided"},{"q":"The class writes in notebooks.","answer":"true","explanation":"Text: they write in their notebooks.","explanation_ar":"يكتبون في الدفاتر.","options":["true","false"],"stage":"guided"},{"q":"Sami and Omar eat lunch alone.","answer":"false","explanation":"They eat together.","explanation_ar":"يأكلان معًا.","options":["true","false"],"stage":"guided"},{"q":"Mr. Khalid asks the class to draw.","answer":"true","explanation":"Text: Draw your favorite part of the day.","explanation_ar":"يطلب منهم الرسم.","options":["true","false"],"stage":"guided"},{"q":"Sami draws a football.","answer":"false","explanation":"Sami draws the moon.","explanation_ar":"يرسم القمر.","options":["true","false"],"stage":"guided"},{"q":"Sami is happy at the end of the day.","answer":"true","explanation":"Text: What a happy day!","explanation_ar":"سامي سعيد.","options":["true","false"],"stage":"guided"}]},{"id":"RW-L01-U3-LS2-A3","type":"highlight","stage":"freer","instructions":"Find the evidence: Mind movie questions. Underline the evidence or choose the best answer.","instructions_ar":"أسئلة الفيلم الذهني: ضع خطًا تحت الدليل أو اختر.","items":[{"q":"Underline the words that help you SEE what Sami writes with.","answer":"Sami writes with his new pencil.","explanation":"This sentence shows the pencil.","explanation_ar":"هذه الجملة تُري القلم.","evidence":"Sami writes with his new pencil.","text_id":"TXT-RW-L01-U3-LS2-1","dok":1,"skill":"visualize","stage":"freer","sentences":["It is Sunday morning.","Sami walks into his classroom.","\"Good morning, Mr.","Khalid!\" he says.","First, the class reads a book about the moon.","Sami likes it!","Next, they write in their notebooks.","Sami writes with his new pencil.","Then, it is time for lunch.","Sami and Omar eat together.","After lunch, they play in the playground.","Last, Mr.","Khalid says, \"Listen, please.","Draw your favorite part of the day.\"","Sami draws the moon.","What a happy day!"]},{"q":"Underline the words you can HEAR in the story.","answer":"\"Good morning, Mr. Khalid!\"","explanation":"Words in quotation marks can be heard.","explanation_ar":"الكلمات بين علامتي التنصيص مسموعة.","evidence":"\"Good morning, Mr. Khalid!\"","text_id":"TXT-RW-L01-U3-LS2-1","dok":1,"skill":"visualize","stage":"freer","sentences":["It is Sunday morning.","Sami walks into his classroom.","\"Good morning, Mr.","Khalid!\" he says.","First, the class reads a book about the moon.","Sami likes it!","Next, they write in their notebooks.","Sami writes with his new pencil.","Then, it is time for lunch.","Sami and Omar eat together.","After lunch, they play in the playground.","Last, Mr.","Khalid says, \"Listen, please.","Draw your favorite part of the day.\"","Sami draws the moon.","What a happy day!"]},{"q":"Why does Sami draw the moon?","answer":"He likes the moon book.","explanation":"The class reads about the moon and Sami likes it.","explanation_ar":"يحب كتاب القمر.","options":["The moon is on the board.","He likes the moon book.","Omar tells him to.","He has no crayons."],"dok":2,"skill":"inference","stage":"freer"},{"q":"Which part of the day comes LAST?","answer":"drawing a favorite part","explanation":"Text: Last, Mr. Khalid says … Draw…","explanation_ar":"الرسم في النهاية.","options":["reading a book","writing in notebooks","drawing a favorite part","eating lunch"],"dok":2,"skill":"sequence","stage":"freer"}]},{"id":"RW-L01-U3-LS2-A4","type":"open","stage":"production","instructions":"Writing: Draw and write.","instructions_ar":"ارسم واكتب.","items":[{"q":"Draw your mind movie for one part. Write one sentence under it.","answer":"Sami and Omar eat lunch together.","explanation":"A drawing + a sentence from the story.","explanation_ar":"رسم + جملة من القصة.","dok":2,"skill":"visualize","stage":"production"},{"q":"What is your favorite part of Sami's day? Why?","answer":"My favorite part is the playground because I like to play.","explanation":"Part + because + reason.","explanation_ar":"الجزء + because + السبب.","dok":3,"skill":"opinion","stage":"production"},{"q":"What is your favorite part of YOUR school day?","answer":"My favorite part is reading.","explanation":"A true sentence.","explanation_ar":"جملة صحيحة.","dok":2,"skill":"connect","stage":"production"},{"q":"Write one question you want to ask Mr. Khalid.","answer":"What is the next book?","explanation":"A question with ?","explanation_ar":"سؤال بعلامة استفهام.","dok":2,"skill":"question","stage":"production"}]},{"id":"RW-L01-U3-LS2-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"A Day at Sami's School\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “A Day at Sami's School”.","answer":"78 words","title":"A Day at Sami's School","body":"It is Sunday morning. Sami walks into his classroom. \"Good morning, Mr. Khalid!\" he says.\n\nFirst, the class reads a book about the moon. Sami likes it!\n\nNext, they write in their notebooks. Sami writes with his new pencil.\n\nThen, it is time for lunch. Sami and Omar eat together. After lunch, they play in the playground.\n\nLast, Mr. Khalid says, \"Listen, please. Draw your favorite part of the day.\" Sami draws the moon. What a happy day!","words":78,"limit":132}],"time_limit_sec":132}],"game":{"name":"Mind Movie Freeze Frame","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Scene sorter: four story scenes appear as film frames in a mixed order; the child drags them into the film strip in the right order, then taps 'Play' to watch the movie with narration.","Teams of four get one part card secretly.","The team plans a 'freeze frame' (a still picture with their bodies) for that part.","The teacher claps the clapper: \"Action!\" The team freezes.","Other teams guess the part and say the sentence from the story.","Correct guess = 1 point for the guessing team and 1 point for a clear freeze frame."],"data":[]},"exit_quiz":[{"q":"When does the story happen?","answer":"on Sunday morning","explanation":"Text: It is Sunday morning.","explanation_ar":"صباح الأحد.","options":["on Friday night","on Sunday morning","after school","in the summer"],"dok":1,"skill":"key details: when"},{"q":"Where does Sami walk in the morning?","answer":"into his classroom","explanation":"Text: walks into his classroom.","explanation_ar":"إلى فصله.","options":["to the park","to the kitchen","to the mosque","into his classroom"],"dok":1,"skill":"key details: where"},{"q":"What do the children do FIRST?","answer":"read a book","explanation":"Text: First, the class reads a book.","explanation_ar":"أولًا يقرؤون.","options":["eat lunch","play outside","read a book","draw the moon"],"dok":1,"skill":"sequence"},{"q":"What is new in the story?","answer":"Sami's pencil","explanation":"Text: his new pencil.","explanation_ar":"قلمه الرصاص جديد.","options":["Sami's pencil","Sami's bag","the classroom","the moon book"],"dok":1,"skill":"key details"},{"q":"What does Mr. Khalid say before the drawing?","answer":"\"Listen, please.\"","explanation":"Text: Listen, please.","explanation_ar":"يقول: استمعوا من فضلكم.","options":["\"Listen, please.\"","\"Go home.\"","\"Eat your lunch.\"","\"Open the window.\""],"dok":1,"skill":"key details"},{"q":"A *mind movie* is ___.","answer":"pictures you make in your head as you read","explanation":"Visualize = see it in your mind.","explanation_ar":"صور تتخيلها أثناء القراءة.","options":["a film at the cinema","pictures you make in your head as you read","a book about the moon","a game in the playground"],"dok":1,"skill":"strategy"},{"q":"*Sami and Omar eat together.* *Together* means ___.","answer":"with each other","explanation":"Together = with each other.","explanation_ar":"together تعني معًا.","options":["one by one","with each other","at home","very fast"],"dok":2,"skill":"word in context"},{"q":"Which sentence helps you HEAR the story?","answer":"\"Good morning, Mr. Khalid!\" he says.","explanation":"Spoken words can be heard.","explanation_ar":"الكلام المنقول نسمعه.","options":["Sami writes with his new pencil.","They play in the playground.","It is Sunday morning.","\"Good morning, Mr. Khalid!\" he says."],"dok":2,"skill":"visualize"},{"q":"How does Sami feel about the moon book?","answer":"He likes it.","explanation":"Text: Sami likes it!","explanation_ar":"يحبه.","options":["He is angry.","He is bored.","He likes it.","He is scared."],"dok":2,"skill":"character feelings"},{"q":"Why is it *a happy day* for Sami?","answer":"He reads, plays with Omar and draws the moon he likes.","explanation":"All the good parts make him happy.","explanation_ar":"الأنشطة الجميلة أسعدته.","options":["He stays at home.","He loses his pencil.","He reads, plays with Omar and draws the moon he likes.","The teacher is sad."],"dok":3,"skill":"inference"}],"images":[{"id":"IMG-RW-L01-U3-LS2-V01","prompt":"Picture for the word 'Sunday': a calendar page with Sunday circled"},{"id":"IMG-RW-L01-U3-LS2-V02","prompt":"Picture for the word 'walk': a boy walking with a school bag"},{"id":"IMG-RW-L01-U3-LS2-V03","prompt":"Picture for the word 'notebook': an open notebook with lines"},{"id":"IMG-RW-L01-U3-LS2-V04","prompt":"Picture for the word 'together': two boys sharing a lunch table"},{"id":"IMG-RW-L01-U3-LS2-V05","prompt":"Picture for the word 'part': a pie chart with one piece pulled out"},{"id":"IMG-RW-L01-U3-LS2-V06","prompt":"Picture for the word 'time': a round clock showing twelve"},{"id":"IMG-RW-L01-U3-LS2-V07","prompt":"Picture for the word 'good morning': a teacher waving at students in the morning sun"},{"id":"IMG-RW-L01-U3-LS2-01","prompt":"The class reads a big book about the moon."},{"id":"IMG-RW-L01-U3-LS2-02","prompt":"Sami and Omar eat lunch together near the playground."},{"id":"IMG-RW-L01-U3-LS2-03","prompt":"An empty film strip with four frames."}],"audio":[{"id":"AUD-RW-L01-U3-LS2-V01","script":"Sunday. We go back to school on Sunday."},{"id":"AUD-RW-L01-U3-LS2-V02","script":"walk. I walk to the mosque."},{"id":"AUD-RW-L01-U3-LS2-V03","script":"notebook. Write it in your notebook."},{"id":"AUD-RW-L01-U3-LS2-V04","script":"together. We eat together."},{"id":"AUD-RW-L01-U3-LS2-V05","script":"part. This is my favorite part of the story."},{"id":"AUD-RW-L01-U3-LS2-V06","script":"time. It is time for lunch."},{"id":"AUD-RW-L01-U3-LS2-V07","script":"good morning. Good morning, class!"},{"id":"AUD-RW-L01-U3-LS2-T1","script":"It is Sunday morning. Sami walks into his classroom. \"Good morning, Mr. Khalid!\" he says. First, the class reads a book about the moon. Sami likes it! Next, they write in their notebooks. Sami writes with his new pencil. Then, it is time for lunch. Sami and Omar eat together. After lunch, they play in the playground. Last, Mr. Khalid says, \"Listen, please. Draw your favorite part of the day.\" Sami draws the moon. What a happy day!"},{"id":"AUD-RW-L01-U3-LS2-VID","script":"Close your eyes. Make a movie in your mind! It is Sunday morning. Sami walks into his classroom… First, the class reads a book about the moon… What can you see? A boy, a bag, a classroom door. What can you hear? \"Good morning!\" First, next, then, last. Each part is a new scene in your mind movie. Now open your eyes. Draw your favorite part and tell a friend why!"}]},{"id":"RW-L01-U3-LS3","title":"Sequence: first, next, last: \"Pack Your School Bag\"","lesson_type":"strategy_paired_text","objectives":["put the events of a story and the steps of a how-to text in order using first, next, then, last","read a short procedural text and follow its steps","retell events in order with a Sequence Train"],"objectives_ar":["ترتيب أحداث القصة وخطوات النص الإرشادي باستخدام first, next, then, last.","قراءة نص إرشادي قصير واتباع خطواته.","إعادة سرد الأحداث بالترتيب باستخدام قطار التسلسل."],"success_criteria":["I can find the order words first, next, then, last.","I can put steps in the right order.","I can retell in order."],"success_criteria_ar":["أستطيع إيجاد كلمات الترتيب.","أستطيع ترتيب الخطوات ترتيبًا صحيحًا.","أستطيع إعادة السرد بالترتيب."],"map_area":"Informational Text: Key Ideas and Details","vocabulary":[{"word":"first","pos":"adverb","ipa":"/fɝst/","definition":"before all the others; number one","arabic":"أولًا","example":"First, wash your hands.","image_id":"IMG-RW-L01-U3-LS3-V01","audio_id":"AUD-RW-L01-U3-LS3-V01","tier":"core"},{"word":"next","pos":"adverb","ipa":"/nɛkst/","definition":"after that; the one after","arabic":"بعد ذلك / التالي","example":"Next, dry your hands.","image_id":"IMG-RW-L01-U3-LS3-V02","audio_id":"AUD-RW-L01-U3-LS3-V02","tier":"core"},{"word":"then","pos":"adverb","ipa":"/ðɛn/","definition":"after that","arabic":"ثم","example":"Then, sit down.","image_id":"IMG-RW-L01-U3-LS3-V03","audio_id":"AUD-RW-L01-U3-LS3-V03","tier":"core"},{"word":"last","pos":"adverb","ipa":"/læst/","definition":"at the end; after all the others","arabic":"أخيرًا","example":"Last, close the door.","image_id":"IMG-RW-L01-U3-LS3-V04","audio_id":"AUD-RW-L01-U3-LS3-V04","tier":"core"},{"word":"put","pos":"verb","ipa":"/pʊt/","definition":"to move something to a place","arabic":"يضع","example":"Put the pen on the desk.","image_id":"IMG-RW-L01-U3-LS3-V05","audio_id":"AUD-RW-L01-U3-LS3-V05","tier":"core"},{"word":"close","pos":"verb","ipa":"/kloʊz/","definition":"to shut; not open","arabic":"يغلق","example":"Close your book.","image_id":"IMG-RW-L01-U3-LS3-V06","audio_id":"AUD-RW-L01-U3-LS3-V06","tier":"core"},{"word":"step","pos":"noun","ipa":"/stɛp/","definition":"one part of a job you do in order","arabic":"خطوة","example":"Step 1 is easy.","image_id":"IMG-RW-L01-U3-LS3-V07","audio_id":"AUD-RW-L01-U3-LS3-V07","tier":"core"}],"explanation":{"text":"**Sequence** means the **order** of things. Stories have events in order. How-to texts have steps in order.\n\nOrder words help us: **First → Next → Then → Last**. Numbers (1, 2, 3, 4) help too.\n\nUse the **Sequence Train**: write the first event in the engine and the last event in the last car.","examples":["Story – **First**, the class reads a book about the moon.","Story – **Next**, they write in their notebooks.","Story – **Then**, Sami and Omar eat lunch and play.","Story – **Last**, Sami draws the moon.","How-to – **First**, open your bag.","How-to – **Next**, put in your books.","How-to – **Then**, put your pen and pencil in the small pocket.","How-to – **Last**, put in your lunch box and close the bag.","Morning – **First**, I wake up. **Next**, I wash. **Then**, I eat breakfast. **Last**, I go to school."],"common_errors":["✗ First I open my bag (no comma). → ✓ First, I open my bag. (Put a comma after the order word.)","✗ Last I am close the bag. → ✓ Last, I close the bag. (No **am** before close.)","✗ Put the books in the bag first and next open the bag. → ✓ First, open the bag. Next, put in the books. (Keep the steps in the right order.)","✗ In the last, close the bag. → ✓ Last, close the bag. (Say **Last,** not *In the last*.)","✗ Then after then… → ✓ Then… / After that… (Do not repeat order words.)","✗ Put pencil in pocket. → ✓ Put your pencil in the pocket. (Add **your** and **the**.)"],"arabic":"التسلسل يعني ترتيب الأشياء: القصة لها أحداث مرتبة، والنص الإرشادي له خطوات مرتبة.\n\nكلمات الترتيب تساعدنا: First (أولًا) ← Next (بعد ذلك) ← Then (ثم) ← Last (أخيرًا)، والأرقام تساعد أيضًا.\n\nاستخدم قطار التسلسل: اكتب أول حدث في القاطرة وآخر حدث في العربة الأخيرة.\n\nانتبه: نضع فاصلة بعد كلمة الترتيب: First, open your bag."},"video":{"script":[{"time":"00:00–00:15","narration":"All aboard the Sequence Train! First, next, then, last!","on_screen":"Sequence Train 🚂","visual":"A toy train with four cars rolls onto the screen; Saqr is the driver."},{"time":"00:15–00:50","narration":"Omar packs his bag. First, he opens his bag. Next, he puts in his books.","on_screen":"First · Next","visual":"Omar opens his bag; books go in; the words fill the engine and car 2."},{"time":"00:50–01:15","narration":"Then, he puts his pen and pencil in the small pocket. Last, he puts in his lunch box and closes the bag.","on_screen":"Then · Last","visual":"Close-ups of the pocket and the zip; cars 3 and 4 fill."},{"time":"01:15–01:45","narration":"Oh no! Omar closes the bag first. Can he put in his books? No! Order is important.","on_screen":"Order is important!","visual":"A funny replay: the bag is closed and books bounce off; a red X appears."},{"time":"01:45–02:15","narration":"Sami's story has order too: read, write, lunch and play, draw.","on_screen":"Story order","visual":"Four story frames hook onto the train cars."},{"time":"02:15–02:30","narration":"Use order words, and your train goes!","on_screen":"First → Next → Then → Last","visual":"The train toots and drives off; the four words stay on the screen."}],"captions_ar":["اركبوا قطار التسلسل! أولًا، بعد ذلك، ثم، أخيرًا!","عمر يجهز حقيبته: أولًا يفتح حقيبته، وبعد ذلك يضع كتبه.","ثم يضع القلمين في الجيب الصغير، وأخيرًا يضع علبة الطعام ويغلق الحقيبة.","يا للمشكلة! عمر أغلق الحقيبة أولًا. هل يستطيع وضع الكتب؟ لا! الترتيب مهم.","قصة سامي لها ترتيب أيضًا: القراءة، الكتابة، الغداء واللعب، ثم الرسم.","استخدم كلمات الترتيب فينطلق قطارك!"],"voice":"Narrator: American English, warm female teacher, speed 0.8. Omar: energetic boy voice. Train sound effects at low volume."},"texts":[{"type":"reading","title":"Pack Your School Bag","body":"You need: your bag, two books, a pen, a pencil and your lunch box.\n\n1. First, open your bag.\n\n2. Next, put in your books.\n\n3. Then, put your pen and pencil in the small pocket.\n\n4. Last, put in your lunch box and close the bag.\n\nNow you are ready for school!","word_count":53,"audio_id":"AUD-RW-L01-U3-LS3-T1","id":"TXT-RW-L01-U3-LS3-1","genre":"procedural","role":"paired","difficulty":"BR–200L","glossary":[{"word":"pocket","definition":"a small part of a bag for small things","arabic":"جيب"},{"word":"lunch box","definition":"a box for your lunch","arabic":"علبة الطعام"}]}],"activities":[{"id":"RW-L01-U3-LS3-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the order word.","instructions_ar":"اختر كلمة الترتيب.","items":[{"q":"Which order word starts the steps?","answer":"First","explanation":"First comes before all the others.","explanation_ar":"First أول الخطوات.","options":["Last","Then","Next","First"],"dok":1,"skill":"order words","stage":"controlled"},{"q":"Which order word ends the steps?","answer":"Last","explanation":"Last is at the end.","explanation_ar":"Last آخر الخطوات.","options":["Last","First","Next","Then"],"dok":1,"skill":"order words","stage":"controlled"},{"q":"In the how-to text, what do you do first?","answer":"open your bag","explanation":"Step 1: First, open your bag.","explanation_ar":"أولًا افتح الحقيبة.","options":["close the bag","put in your books","put in your lunch box","open your bag"],"dok":1,"skill":"sequence","text_id":"TXT-RW-L01-U3-LS3-1","stage":"controlled"},{"q":"Where do the pen and pencil go?","answer":"in the small pocket","explanation":"Step 3: in the small pocket.","explanation_ar":"في الجيب الصغير.","options":["in the lunch box","on the desk","in the small pocket","under the bag"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Which step comes after *put in your books*?","answer":"Put your pen and pencil in the small pocket.","explanation":"Step 3 comes after step 2.","explanation_ar":"الخطوة الثالثة بعد الثانية.","options":["Put your pen and pencil in the small pocket.","Open your bag.","Wake up.","Read a book."],"dok":1,"skill":"sequence","stage":"controlled"},{"q":"How many things do you need?","answer":"five","explanation":"Bag, books, pen, pencil, lunch box = five things.","explanation_ar":"خمسة أشياء.","options":["two","five","three","seven"],"dok":2,"skill":"key details","stage":"controlled"}]},{"id":"RW-L01-U3-LS3-A2","type":"sequence","stage":"guided","instructions":"Put in order: Put the steps in order.","instructions_ar":"رتّب الخطوات.","items":[{"q":"Order the steps for packing a bag.","answer":"Open your bag. → Put in your books. → Put in your pens. → Close the bag.","explanation":"open → books → pens → close","explanation_ar":"افتح ← الكتب ← الأقلام ← أغلق.","stage":"guided","parts":["Open your bag.","Close the bag.","Put in your books.","Put in your pens."],"target":["Open your bag.","Put in your books.","Put in your pens.","Close the bag."]},{"q":"Order the parts of Sami's day.","answer":"The class reads a book. → They write in notebooks. → They eat lunch. → Sami draws the moon.","explanation":"Story order from the text.","explanation_ar":"ترتيب القصة.","stage":"guided","parts":["Sami draws the moon.","They write in notebooks.","The class reads a book.","They eat lunch."],"target":["The class reads a book.","They write in notebooks.","They eat lunch.","Sami draws the moon."]},{"q":"Order the steps of a school morning.","answer":"Wake up. → Wash your face. → Eat breakfast. → Go to school.","explanation":"A morning routine in order.","explanation_ar":"روتين الصباح بالترتيب.","stage":"guided","parts":["Wake up.","Eat breakfast.","Wash your face.","Go to school."],"target":["Wake up.","Wash your face.","Eat breakfast.","Go to school."]},{"q":"Order the steps for writing your name on a test.","answer":"Take a pencil. → Write your name. → Check the capital letter. → Give the paper to the teacher.","explanation":"Take → write → check → give.","explanation_ar":"خذ ← اكتب ← راجع ← سلّم.","stage":"guided","parts":["Give the paper to the teacher.","Check the capital letter.","Write your name.","Take a pencil."],"target":["Take a pencil.","Write your name.","Check the capital letter.","Give the paper to the teacher."]},{"q":"Order the steps for drinking water.","answer":"Get a cup. → Fill it with water. → Drink the water. → Wash the cup.","explanation":"Cup → fill → drink → wash.","explanation_ar":"كوب ← املأ ← اشرب ← اغسل.","stage":"guided","parts":["Get a cup.","Wash the cup.","Fill it with water.","Drink the water."],"target":["Get a cup.","Fill it with water.","Drink the water.","Wash the cup."]},{"q":"Order the steps for starting the school day.","answer":"Open the door. → Walk into the classroom. → Say good morning. → Sit at your desk.","explanation":"Door → walk in → greet → sit.","explanation_ar":"الباب ← ادخل ← حيِّ ← اجلس.","stage":"guided","parts":["Sit at your desk.","Open the door.","Say good morning.","Walk into the classroom."],"target":["Open the door.","Walk into the classroom.","Say good morning.","Sit at your desk."]}]},{"id":"RW-L01-U3-LS3-A3","type":"organizer","stage":"freer","instructions":"Organizer: Fill in the Sequence Train for *Pack Your School Bag*. Use the order words.","instructions_ar":"أكمل قطار التسلسل لنص تجهيز الحقيبة.","items":[{"q":"Engine: First, …","answer":"First, open your bag.","explanation":"Step 1.","explanation_ar":"الخطوة 1.","dok":1,"skill":"sequence","stage":"freer"},{"q":"Car 2: Next, …","answer":"Next, put in your books.","explanation":"Step 2.","explanation_ar":"الخطوة 2.","dok":1,"skill":"sequence","stage":"freer"},{"q":"Car 3: Then, …","answer":"Then, put your pen and pencil in the small pocket.","explanation":"Step 3.","explanation_ar":"الخطوة 3.","dok":1,"skill":"sequence","stage":"freer"},{"q":"Last car: Last, …","answer":"Last, put in your lunch box and close the bag.","explanation":"Step 4.","explanation_ar":"الخطوة 4.","dok":1,"skill":"sequence","stage":"freer"}]},{"id":"RW-L01-U3-LS3-A4","type":"open","stage":"production","instructions":"Writing: Write your own steps.","instructions_ar":"اكتب خطواتك الخاصة.","items":[{"q":"What do you do FIRST when you come to class?","answer":"First, I say good morning.","explanation":"First, + action.","explanation_ar":"First, + فعل.","dok":1,"skill":"sequence","stage":"production"},{"q":"What do you do NEXT?","answer":"Next, I sit at my desk.","explanation":"Next, + action.","explanation_ar":"Next, + فعل.","dok":1,"skill":"sequence","stage":"production"},{"q":"What do you do THEN?","answer":"Then, I open my book.","explanation":"Then, + action.","explanation_ar":"Then, + فعل.","dok":1,"skill":"sequence","stage":"production"},{"q":"What do you do LAST, at the end of the day?","answer":"Last, I go home.","explanation":"Last, + action.","explanation_ar":"Last, + فعل.","dok":1,"skill":"sequence","stage":"production"}]},{"id":"RW-L01-U3-LS3-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"Pack Your School Bag\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “Pack Your School Bag”.","answer":"53 words","title":"Pack Your School Bag","body":"You need: your bag, two books, a pen, a pencil and your lunch box.\n\n1. First, open your bag.\n\n2. Next, put in your books.\n\n3. Then, put your pen and pencil in the small pocket.\n\n4. Last, put in your lunch box and close the bag.\n\nNow you are ready for school!","words":53,"limit":94}],"time_limit_sec":94},{"id":"RW-L01-U3-LS3-ORG","type":"organizer","organizer":"Sequence Train","instructions":"Organizer: Write one step in each car. Start with the engine.","items":[{"q":"Engine – First","answer":"Open your bag."},{"q":"Car 2 – Next","answer":"Put in your books."},{"q":"Car 3 – Then","answer":"Put your pen and pencil in the small pocket."},{"q":"Last car – Last","answer":"Put in your lunch box and close the bag."}]}],"game":{"name":"Sequence Train Race","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Train race: four cars with sentences appear on a platform; the child drags them onto the track in order. The train leaves when the order is right; beat the clock on 6 tracks.","Each pair gets an envelope.","On \"Go!\", they put the four cars in order on the desk.","They raise their hands and read the steps with order words.","The teacher checks: correct = 1 point; fastest correct pair = 1 bonus point.","Pairs swap envelopes; play 6 rounds."],"data":[]},"exit_quiz":[{"q":"*Sequence* means ___.","answer":"the order of things","explanation":"Sequence = order.","explanation_ar":"التسلسل يعني الترتيب.","options":["the order of things","a kind of bag","a long story","a picture"],"dok":1,"skill":"strategy"},{"q":"Which word comes between *First* and *Then*?","answer":"Next","explanation":"First → Next → Then → Last.","explanation_ar":"Next بين First وThen.","options":["Last","Before","Finish","Next"],"dok":1,"skill":"order words"},{"q":"In the how-to text, what is the last step?","answer":"Put in your lunch box and close the bag.","explanation":"Step 4 is last.","explanation_ar":"الخطوة 4 هي الأخيرة.","options":["Open your bag.","Put in your books.","Put in your lunch box and close the bag.","Put your pen in the pocket."],"dok":1,"skill":"sequence"},{"q":"Why do we open the bag first?","answer":"We cannot put things in a closed bag.","explanation":"Order matters: open before putting in.","explanation_ar":"لا نضع الأشياء في حقيبة مغلقة.","options":["The bag is big.","The bag is new.","We like to close it.","We cannot put things in a closed bag."],"dok":2,"skill":"reasoning"},{"q":"What kind of text is *Pack Your School Bag*?","answer":"a how-to text with steps","explanation":"It tells you how to do something.","explanation_ar":"نص إرشادي بخطوات.","options":["a story about a family","a how-to text with steps","a poem with rhymes","a note to Grandma"],"dok":1,"skill":"genre"},{"q":"Which sentence uses an order word correctly?","answer":"First, wash your hands.","explanation":"Order word + comma + step.","explanation_ar":"كلمة الترتيب ثم فاصلة.","options":["First, wash your hands.","First wash, your hands.","Wash first, your, hands.","Your hands first wash."],"dok":2,"skill":"order words"},{"q":"In Sami's story, what happens before lunch?","answer":"They write in notebooks.","explanation":"Writing is the 'next' part, before lunch.","explanation_ar":"الكتابة قبل الغداء.","options":["They write in notebooks.","They play in the playground.","Sami draws the moon.","They go home."],"dok":2,"skill":"sequence"},{"q":"What do you need for the how-to text?","answer":"a bag, books, a pen, a pencil and a lunch box","explanation":"The 'You need' line lists them.","explanation_ar":"سطر You need يذكرها.","options":["a ball and a kite","a cup and water","a bag, books, a pen, a pencil and a lunch box","a camel and a tent"],"dok":1,"skill":"key details"},{"q":"What does *Close the bag* mean?","answer":"Shut the bag.","explanation":"Close = shut.","explanation_ar":"close تعني أغلق.","options":["Open the bag.","Shut the bag.","Buy a bag.","Wash the bag."],"dok":1,"skill":"vocabulary"},{"q":"Which group is in the right order for a morning?","answer":"wake up, wash, eat breakfast, go to school","explanation":"We wake up first and go to school last.","explanation_ar":"نستيقظ أولًا ونذهب إلى المدرسة أخيرًا.","options":["go to school, wake up, wash, eat breakfast","eat breakfast, go to school, wake up, wash","wake up, wash, eat breakfast, go to school","wash, go to school, eat breakfast, wake up"],"dok":3,"skill":"sequence"}],"images":[{"id":"IMG-RW-L01-U3-LS3-V01","prompt":"Picture for the word 'first': a podium with a child on the number 1 step"},{"id":"IMG-RW-L01-U3-LS3-V02","prompt":"Picture for the word 'next': an arrow pointing to the second box in a row"},{"id":"IMG-RW-L01-U3-LS3-V03","prompt":"Picture for the word 'then': a third box lighting up in a row of four"},{"id":"IMG-RW-L01-U3-LS3-V04","prompt":"Picture for the word 'last': the last car of a toy train with a flag"},{"id":"IMG-RW-L01-U3-LS3-V05","prompt":"Picture for the word 'put': a hand putting a pen on a desk"},{"id":"IMG-RW-L01-U3-LS3-V06","prompt":"Picture for the word 'close': a hand closing a book"},{"id":"IMG-RW-L01-U3-LS3-V07","prompt":"Picture for the word 'step': a staircase with numbers 1, 2, 3, 4"},{"id":"IMG-RW-L01-U3-LS3-01","prompt":"Four pictures show how to pack a school bag."},{"id":"IMG-RW-L01-U3-LS3-02","prompt":"A train with four empty cars for writing steps."},{"id":"IMG-RW-L01-U3-LS3-03","prompt":"Omar is surprised because books bounce off a closed bag."}],"audio":[{"id":"AUD-RW-L01-U3-LS3-V01","script":"first. First, wash your hands."},{"id":"AUD-RW-L01-U3-LS3-V02","script":"next. Next, dry your hands."},{"id":"AUD-RW-L01-U3-LS3-V03","script":"then. Then, sit down."},{"id":"AUD-RW-L01-U3-LS3-V04","script":"last. Last, close the door."},{"id":"AUD-RW-L01-U3-LS3-V05","script":"put. Put the pen on the desk."},{"id":"AUD-RW-L01-U3-LS3-V06","script":"close. Close your book."},{"id":"AUD-RW-L01-U3-LS3-V07","script":"step. Step 1 is easy."},{"id":"AUD-RW-L01-U3-LS3-T1","script":"You need: your bag, two books, a pen, a pencil and your lunch box. 1. First, open your bag. 2. Next, put in your books. 3. Then, put your pen and pencil in the small pocket. 4. Last, put in your lunch box and close the bag. Now you are ready for school!"},{"id":"AUD-RW-L01-U3-LS3-VID","script":"All aboard the Sequence Train! First, next, then, last! Omar packs his bag. First, he opens his bag. Next, he puts in his books. Then, he puts his pen and pencil in the small pocket. Last, he puts in his lunch box and closes the bag. Oh no! Omar closes the bag first. Can he put in his books? No! Order is important. Sami's story has order too: read, write, lunch and play, draw. Use order words, and your train goes!"}]},{"id":"RW-L01-U3-LS4","title":"Writing Skill: Action words in simple sentences","lesson_type":"writing_skill","objectives":["write simple sentences with a 'who' (I, we, a name) and an action word","add -s to the action word after he, she or one name (Sami plays)","avoid the common errors 'I am play' and sentences with no 'who'"],"objectives_ar":["كتابة جمل بسيطة فيها فاعل (I, we, اسم) وكلمة فعل.","إضافة s إلى الفعل بعد he أو she أو اسم واحد.","تجنب الخطأين الشائعين: I am play والجملة بلا فاعل."],"success_criteria":["I can find the who and the action word in a sentence.","I can write I + action word sentences.","I can add -s after he, she or a name."],"success_criteria_ar":["أستطيع إيجاد الفاعل والفعل في الجملة.","أستطيع كتابة جمل I + فعل.","أستطيع إضافة s بعد he وshe والاسم."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"action word","pos":"noun","ipa":"/ˈækʃən wɝd/","definition":"a word for what someone does (a verb)","arabic":"كلمة فعل","example":"*Run* is an action word.","image_id":"IMG-RW-L01-U3-LS4-V01","audio_id":"AUD-RW-L01-U3-LS4-V01","tier":"core"},{"word":"who","pos":"pronoun","ipa":"/hu/","definition":"the person or thing that does the action","arabic":"مَن (الفاعل)","example":"In *I read*, the who is *I*.","image_id":"IMG-RW-L01-U3-LS4-V02","audio_id":"AUD-RW-L01-U3-LS4-V02","tier":"core"},{"word":"walk","pos":"verb","ipa":"/wɔk/","definition":"to move on your feet","arabic":"يمشي","example":"We walk to the mosque.","image_id":"IMG-RW-L01-U3-LS4-V03","audio_id":"AUD-RW-L01-U3-LS4-V03","tier":"core"},{"word":"eat","pos":"verb","ipa":"/it/","definition":"to put food in your mouth and swallow it","arabic":"يأكل","example":"I eat an apple.","image_id":"IMG-RW-L01-U3-LS4-V04","audio_id":"AUD-RW-L01-U3-LS4-V04","tier":"core"},{"word":"play","pos":"verb","ipa":"/pleɪ/","definition":"to have fun with a game or toy","arabic":"يلعب","example":"They play football.","image_id":"IMG-RW-L01-U3-LS4-V05","audio_id":"AUD-RW-L01-U3-LS4-V05","tier":"core"},{"word":"sandwich","pos":"noun","ipa":"/ˈsænwɪtʃ/","definition":"two pieces of bread with food between them","arabic":"شطيرة","example":"My sandwich has cheese.","image_id":"IMG-RW-L01-U3-LS4-V06","audio_id":"AUD-RW-L01-U3-LS4-V06","tier":"core"},{"word":"sit","pos":"verb","ipa":"/sɪt/","definition":"to rest on a chair","arabic":"يجلس","example":"Sit on your chair.","image_id":"IMG-RW-L01-U3-LS4-V07","audio_id":"AUD-RW-L01-U3-LS4-V07","tier":"core"}],"explanation":{"text":"A sentence needs a **WHO** and an **ACTION WORD**. The who does the action.\n\n**I** + action word: *I read. I write. I play.* (No *am*!)\n\n**He, she** or **one name** + action word **+ s**: *Sami plays. She reads. He writes.*\n\n**We, they** + action word: *We listen. They eat.*","examples":["**I walk** to school.","**I read** a book.","**We listen** to the teacher.","**They eat** lunch.","**Sami plays** football.","**Noura writes** a story.","**Layla draws** a palm tree.","**Mr. Khalid opens** the door.","**The children sit** at their desks."],"common_errors":["✗ I am play football. → ✓ I play football. (No **am** before the action word.)","✗ Plays football. → ✓ Omar plays football. (In Arabic يلعب has a hidden who; English needs the who.)","✗ Sami play in the playground. → ✓ Sami plays in the playground. (One name → add **-s**.)","✗ She go to school. → ✓ She goes to school. (go → **goes** with he/she.)","✗ We is write. → ✓ We write. (No *is*; just we + action word.)","✗ I eats a sandwich. → ✓ I eat a sandwich. (With **I**, no -s.)"],"arabic":"الجملة تحتاج إلى فاعل (مَن قام بالفعل) وكلمة فعل.\n\nمع I نكتب الفعل كما هو دون am: I read. I play.\n\nمع he أو she أو اسم شخص واحد نضيف s إلى الفعل: Sami plays. She reads.\n\nفي العربية يمكن أن يكون الفاعل مستترًا مثل \"يلعب\"، أما في الإنجليزية فلا بد من ذكر الفاعل: Omar plays."},"video":{"script":[{"time":"00:00–00:15","narration":"Every sentence has a team: a WHO and an ACTION WORD!","on_screen":"WHO + ACTION","visual":"Two cartoon blocks, 'WHO' and 'ACTION', click together like puzzle pieces."},{"time":"00:15–00:45","narration":"I read. I write. I play. With I, just the action word!","on_screen":"I + read","visual":"Omar holds up cards: I + read, I + write, I + play."},{"time":"00:45–01:15","narration":"Sami plays. Noura writes. One person – add s! Pop!","on_screen":"Sami play + s","visual":"An 's' pops onto 'play' with a bubble sound."},{"time":"01:15–01:40","narration":"Oh no! 'I am play.' Too many words. Take out am!","on_screen":"I am play ✗ → I play ✓","visual":"The word 'am' is pushed off the sentence by Saqr."},{"time":"01:40–02:10","narration":"Where is the who? 'Plays football.' Who plays? Omar plays football!","on_screen":"Who? → Omar plays football.","visual":"A question mark appears; Omar jumps into the empty space."},{"time":"02:10–02:30","narration":"Who plus action – your sentence is ready!","on_screen":"WHO + ACTION = sentence ✔","visual":"The puzzle pieces click; confetti."}],"captions_ar":["كل جملة فيها فريق: فاعل وكلمة فعل!","مع I نكتب الفعل وحده: I read. I write. I play.","سامي يلعب: Sami plays. شخص واحد؟ أضف s!","خطأ: I am play. كلمات زائدة! احذف am.","أين الفاعل؟ Plays football. مَن يلعب؟ Omar plays football!","فاعل + فعل = جملتك جاهزة!"],"voice":"Narrator: American English, warm female teacher, speed 0.8. Omar: energetic boy. Fun 'pop' sound when -s is added."},"texts":[{"type":"model","title":"At School (from Omar's Notebook)","body":"I am Omar. I walk to school with my brother. I read with my class. I write in my notebook.\n\nI listen to Mr. Khalid. At lunch, I eat a sandwich. Then I play football in the playground. Sami plays with me!","word_count":42,"audio_id":"AUD-RW-L01-U3-LS4-T1","id":"TXT-RW-L01-U3-LS4-1","genre":"model text","role":"model","difficulty":"BR–200L","glossary":[],"annotations":["**I walk** – every sentence has a WHO (I) and an ACTION WORD (walk).","**I read**, **I write**, **I listen** – with *I*, the action word has no -s.","**Sami plays** – with one other person (he, she, Sami), add -s to the action word.","**I listen to Mr. Khalid** – say *listen to*.","**At lunch, I eat** – a time word can come first, then a comma.","Each sentence starts with a capital letter and ends with a period or an exclamation mark."]}],"activities":[{"id":"RW-L01-U3-LS4-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Find the action word in each sentence.","instructions_ar":"ابحث عن كلمة الفعل في كل جملة.","items":[{"q":"*Layla draws a cat.* What is the action word?","answer":"draws","explanation":"Draws tells what Layla does.","explanation_ar":"ترسم هي الفعل.","options":["Layla","draws","cat","a"],"dok":1,"skill":"action words","stage":"controlled"},{"q":"*We listen to the story.* What is the action word?","answer":"listen","explanation":"Listen tells what we do.","explanation_ar":"نستمع هي الفعل.","options":["We","story","the","listen"],"dok":1,"skill":"action words","stage":"controlled"},{"q":"*Omar kicks the ball.* Who does the action?","answer":"Omar","explanation":"Omar does the kicking.","explanation_ar":"عمر هو الفاعل.","options":["Omar","kicks","ball","the"],"dok":1,"skill":"who","stage":"controlled"},{"q":"*The baby sleeps.* Who does the action?","answer":"the baby","explanation":"The baby does the sleeping.","explanation_ar":"الرضيع هو الفاعل.","options":["sleeps","night","the baby","bed"],"dok":1,"skill":"who","stage":"controlled"},{"q":"*They eat sandwiches at lunch.* What is the action word?","answer":"eat","explanation":"Eat tells what they do.","explanation_ar":"يأكلون هي الفعل.","options":["They","sandwiches","lunch","eat"],"dok":1,"skill":"action words","stage":"controlled"},{"q":"*Mr. Khalid opens the window.* Who does the action?","answer":"Mr. Khalid","explanation":"Mr. Khalid opens it.","explanation_ar":"الأستاذ خالد هو الفاعل.","options":["opens","Mr. Khalid","window","the"],"dok":1,"skill":"who","stage":"controlled"}]},{"id":"RW-L01-U3-LS4-A2","type":"gap_fill","stage":"guided","instructions":"Guided practice: Choose the right action word from the bank.","instructions_ar":"اختر الفعل المناسب من البنك.","items":[{"q":"I ________ to school with my father.","answer":"walk","explanation":"With I, no -s.","explanation_ar":"مع I بدون s.","stage":"guided"},{"q":"Noura ________ a story in her notebook.","answer":"writes","explanation":"One name → -s.","explanation_ar":"اسم واحد ← s.","stage":"guided"},{"q":"We ________ on our chairs.","answer":"sit","explanation":"With we, no -s.","explanation_ar":"مع we بدون s.","stage":"guided"},{"q":"Sami ________ football with Omar.","answer":"plays","explanation":"One name → -s.","explanation_ar":"اسم واحد ← s.","stage":"guided"},{"q":"They ________ a sandwich at lunch.","answer":"eat","explanation":"With they, no -s.","explanation_ar":"مع they بدون s.","stage":"guided"},{"q":"She ________ to the teacher.","answer":"listens","explanation":"She → -s.","explanation_ar":"مع she نضيف s.","stage":"guided"}]},{"id":"RW-L01-U3-LS4-A3","type":"open","stage":"freer","instructions":"Freer practice: Fix the sentences. Write them correctly.","instructions_ar":"صحّح الجمل واكتبها بشكل صحيح.","items":[{"q":"I am read a book.","answer":"I read a book.","explanation":"Take out am.","explanation_ar":"احذف am.","dok":2,"skill":"editing","stage":"freer"},{"q":"Reads a book. (Who? Adam)","answer":"Adam reads a book.","explanation":"Add the who.","explanation_ar":"أضف الفاعل.","dok":2,"skill":"editing","stage":"freer"},{"q":"Layla draw a palm tree.","answer":"Layla draws a palm tree.","explanation":"Add -s.","explanation_ar":"أضف s.","dok":2,"skill":"editing","stage":"freer"},{"q":"we eats lunch together","answer":"We eat lunch together.","explanation":"Capital W, no -s with we, period.","explanation_ar":"W كبيرة، بدون s، ونقطة.","dok":2,"skill":"editing","stage":"freer"}]},{"id":"RW-L01-U3-LS4-A4","type":"open","stage":"production","instructions":"Writing: Write 4 sentences about your school day. Use a who and an action word.","instructions_ar":"اكتب 4 جمل عن يومك المدرسي فيها فاعل وفعل.","items":[{"q":"Write an I sentence about the morning.","answer":"I walk to school.","explanation":"I + action word.","explanation_ar":"I + فعل.","dok":1,"skill":"sentence writing","stage":"production"},{"q":"Write an I sentence about the classroom.","answer":"I write in my notebook.","explanation":"I + action word.","explanation_ar":"I + فعل.","dok":1,"skill":"sentence writing","stage":"production"},{"q":"Write a sentence about a friend. Use -s.","answer":"Majed draws a car.","explanation":"Name + action word + s.","explanation_ar":"اسم + فعل + s.","dok":2,"skill":"sentence writing","stage":"production"},{"q":"Write a We sentence about lunch or play.","answer":"We play in the playground.","explanation":"We + action word.","explanation_ar":"We + فعل.","dok":1,"skill":"sentence writing","stage":"production"}]}],"game":{"name":"Who + Action Slot Machine","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Slot machine: two reels spin (WHO and ACTION); when they stop, the child decides whether to add the -s tile and says or types the sentence. Correct = coins and a sound; 10 spins.","A player pulls one WHO card and one ACTION card.","The player says a full sentence (Noura + read → \"Noura reads a book.\").","If the sentence needs -s, the player must hold up the 's' card.","Correct sentence = 1 point; correct use of the 's' card = 1 bonus point.","Teams take turns for 10 rounds."],"data":[]},"exit_quiz":[{"q":"A sentence needs a who and ___.","answer":"an action word","explanation":"Who + action word = sentence.","explanation_ar":"فاعل + فعل.","options":["a picture","a number","a title","an action word"],"dok":1,"skill":"rule"},{"q":"Which sentence about the playground is correct?","answer":"I play in the playground.","explanation":"I + action word, no am, no -s.","explanation_ar":"I + فعل بدون am أو s.","options":["I am play in the playground.","I plays in the playground.","I play in the playground.","Play in the playground I."],"dok":1,"skill":"sentences"},{"q":"Which sentence about Noura's book is correct?","answer":"Noura reads a book.","explanation":"One name → reads.","explanation_ar":"اسم واحد ← reads.","options":["Noura read a book.","Noura reads a book.","Noura am reads a book.","Reads a book Noura."],"dok":1,"skill":"-s"},{"q":"Find the who: *My brother eats a sandwich.*","answer":"My brother","explanation":"My brother does the eating.","explanation_ar":"أخي هو الفاعل.","options":["eats","My brother","a sandwich","sandwich eats"],"dok":1,"skill":"who"},{"q":"Find the action word: *We sit at our desks.*","answer":"sit","explanation":"Sit tells what we do.","explanation_ar":"sit هي الفعل.","options":["We","desks","sit","our"],"dok":1,"skill":"action words"},{"q":"What is missing? *Walks to school every day.*","answer":"the who","explanation":"We do not know who walks.","explanation_ar":"ينقصها الفاعل.","options":["the who","the action word","a period","a capital letter"],"dok":2,"skill":"editing"},{"q":"Choose the word: *Grandpa Saleh ___ a story.*","answer":"tells","explanation":"One name → tells.","explanation_ar":"اسم واحد ← tells.","options":["tell","telling","am tell","tells"],"dok":2,"skill":"-s"},{"q":"Choose the word: *My friends and I ___ in the playground.*","answer":"run","explanation":"My friends and I = we → run.","explanation_ar":"نحن ← run.","options":["runs","run","am run","is run"],"dok":2,"skill":"agreement"},{"q":"What is wrong? *She go to the library.*","answer":"It needs *goes*.","explanation":"She → goes.","explanation_ar":"مع she نقول goes.","options":["It needs *goes*.","It needs *went*.","It needs *am*.","Nothing is wrong."],"dok":2,"skill":"-s"},{"q":"Which sentence tells what Omar does at lunch?","answer":"Omar eats a sandwich at lunch.","explanation":"It has a who and an action word.","explanation_ar":"فيها فاعل وفعل.","options":["Omar at lunch.","Eats Omar a sandwich.","Omar eats a sandwich at lunch.","At lunch a sandwich."],"dok":3,"skill":"sentences"}],"images":[{"id":"IMG-RW-L01-U3-LS4-V01","prompt":"Picture for the word 'action word': a child running with motion lines and the word card beside"},{"id":"IMG-RW-L01-U3-LS4-V02","prompt":"Picture for the word 'who': a spotlight on a child at the start of a sentence strip"},{"id":"IMG-RW-L01-U3-LS4-V03","prompt":"Picture for the word 'walk': a father and son walking"},{"id":"IMG-RW-L01-U3-LS4-V04","prompt":"Picture for the word 'eat': a child eating an apple"},{"id":"IMG-RW-L01-U3-LS4-V05","prompt":"Picture for the word 'play': children kicking a ball"},{"id":"IMG-RW-L01-U3-LS4-V06","prompt":"Picture for the word 'sandwich': a cheese sandwich cut in half"},{"id":"IMG-RW-L01-U3-LS4-V07","prompt":"Picture for the word 'sit': a girl sitting on a chair"},{"id":"IMG-RW-L01-U3-LS4-01","prompt":"Omar's notebook with a football sticker."},{"id":"IMG-RW-L01-U3-LS4-02","prompt":"Two puzzle pieces, one for who and one for action, joining together."},{"id":"IMG-RW-L01-U3-LS4-03","prompt":"A toy slot machine with two reels."}],"audio":[{"id":"AUD-RW-L01-U3-LS4-V01","script":"action word. *Run* is an action word."},{"id":"AUD-RW-L01-U3-LS4-V02","script":"who. In *I read*, the who is *I*."},{"id":"AUD-RW-L01-U3-LS4-V03","script":"walk. We walk to the mosque."},{"id":"AUD-RW-L01-U3-LS4-V04","script":"eat. I eat an apple."},{"id":"AUD-RW-L01-U3-LS4-V05","script":"play. They play football."},{"id":"AUD-RW-L01-U3-LS4-V06","script":"sandwich. My sandwich has cheese."},{"id":"AUD-RW-L01-U3-LS4-V07","script":"sit. Sit on your chair."},{"id":"AUD-RW-L01-U3-LS4-T1","script":"I am Omar. I walk to school with my brother. I read with my class. I write in my notebook. I listen to Mr. Khalid. At lunch, I eat a sandwich. Then I play football in the playground. Sami plays with me!"},{"id":"AUD-RW-L01-U3-LS4-VID","script":"Every sentence has a team: a WHO and an ACTION WORD! I read. I write. I play. With I, just the action word! Sami plays. Noura writes. One person – add s! Pop! Oh no! 'I am play.' Too many words. Take out am! Where is the who? 'Plays football.' Who plays? Omar plays football! Who plus action – your sentence is ready!"}]},{"id":"RW-L01-U3-LS5","title":"Writing Workshop: My School Day","lesson_type":"writing_workshop","objectives":["plan a school day in four pictures in order","write 4 sentences about their school day with First, Next, Then and Last, each with a who and an action word","revise by adding a place or a thing, edit, and publish in a class book"],"objectives_ar":["التخطيط ليوم دراسي في أربع صور مرتبة.","كتابة 4 جمل عن يومهم الدراسي باستخدام كلمات الترتيب، في كل منها فاعل وفعل.","التحسين بإضافة مكان أو شيء، ثم التدقيق والنشر في كتاب الفصل."],"success_criteria":["I can plan my day in four pictures.","I can write 4 sentences with order words.","I can check my who, action word, capitals and periods."],"success_criteria_ar":["أستطيع التخطيط ليومي في أربع صور.","أستطيع كتابة 4 جمل بكلمات الترتيب.","أستطيع مراجعة الفاعل والفعل والحروف الكبيرة والنقاط."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"day","pos":"noun","ipa":"/deɪ/","definition":"the time from morning to night","arabic":"يوم","example":"Today is a good day.","image_id":"IMG-RW-L01-U3-LS5-V01","audio_id":"AUD-RW-L01-U3-LS5-V01","tier":"core"},{"word":"class","pos":"noun","ipa":"/klæs/","definition":"a group of students who learn together","arabic":"صف / حصة","example":"Our class has 25 students.","image_id":"IMG-RW-L01-U3-LS5-V02","audio_id":"AUD-RW-L01-U3-LS5-V02","tier":"core"},{"word":"math","pos":"noun","ipa":"/mæθ/","definition":"the school subject about numbers","arabic":"الرياضيات","example":"I count in math.","image_id":"IMG-RW-L01-U3-LS5-V03","audio_id":"AUD-RW-L01-U3-LS5-V03","tier":"core"},{"word":"art","pos":"noun","ipa":"/ɑrt/","definition":"the school subject where we draw and paint","arabic":"التربية الفنية","example":"We paint in art.","image_id":"IMG-RW-L01-U3-LS5-V04","audio_id":"AUD-RW-L01-U3-LS5-V04","tier":"core"},{"word":"science","pos":"noun","ipa":"/ˈsaɪəns/","definition":"the school subject about plants, animals and the world","arabic":"العلوم","example":"We look at plants in science.","image_id":"IMG-RW-L01-U3-LS5-V05","audio_id":"AUD-RW-L01-U3-LS5-V05","tier":"core"},{"word":"go home","pos":"verb","ipa":"/ɡoʊ hoʊm/","definition":"to return to your house","arabic":"يعود إلى المنزل","example":"We go home at one o'clock.","image_id":"IMG-RW-L01-U3-LS5-V06","audio_id":"AUD-RW-L01-U3-LS5-V06","tier":"core"},{"word":"finish","pos":"verb","ipa":"/ˈfɪnɪʃ/","definition":"to come to the end","arabic":"يُنهي / ينتهي","example":"I finish my work.","image_id":"IMG-RW-L01-U3-LS5-V07","audio_id":"AUD-RW-L01-U3-LS5-V07","tier":"core"}],"explanation":{"text":"To write about your day, use **order words**: **First, Next, Then, Last.**\n\nEvery sentence needs a **who** and an **action word**: *First, I read a book.*\n\n**Revise**: add **where** or **what** to make it better: *Then, I play* → *Then, I play football in the playground.*","examples":["Opening: **This is my school day.**","**First, I** say good morning to my teacher.","**First, we** read a story in class.","**Next, I** count numbers in math.","**Next, we** paint in art.","**Then, I** eat lunch with my friend.","**Then, we** play in the playground.","**Last, I** go home on the bus.","Revise: *Last, I go home.* → **Last, I go home with my father.**"],"common_errors":["✗ First I go school. → ✓ First, I go to school. (Comma after First; say **go to school**.)","✗ Then I am eat lunch. → ✓ Then, I eat lunch. (No **am** before the action word.)","✗ Finish, I go home. → ✓ Last, I go home. (Use **Last** as the order word.)","✗ Next, play football. → ✓ Next, I play football. (Do not forget the **who**.)","✗ In the math I count. → ✓ In math, I count. (No *the* before school subjects.)","✗ Last, we goes home. → ✓ Last, we go home. (With **we**, no -s.)"],"arabic":"لتكتب عن يومك استخدم كلمات الترتيب: First, Next, Then, Last.\n\nكل جملة تحتاج إلى فاعل وفعل، مثل: First, I read a book.\n\nحسِّن جملتك بإضافة المكان أو الشيء: Then, I play football in the playground.\n\nانتبه: لا نضع the قبل أسماء المواد الدراسية: in math، in art."},"video":{"script":[{"time":"00:00–00:15","narration":"Adam writes about his school day. Let's watch!","on_screen":"My School Day","visual":"Adam rolls up to his desk in his blue wheelchair and opens his tablet and notebook."},{"time":"00:15–00:45","narration":"Plan: Adam draws four boxes – science, math, lunch, home.","on_screen":"1 Plan – 4 pictures","visual":"Four boxes fill with quick sketches: a magnifying glass, numbers, a lunch box, a bus."},{"time":"00:45–01:20","narration":"Draft: This is my school day. First, I look at plants in science. Next, I count in math. Then, I eat lunch. Last, I go home.","on_screen":"2 Draft – First · Next · Then · Last","visual":"Each sentence types onto the page; the order words glow coral."},{"time":"01:20–01:45","narration":"Revise: Then, I eat lunch… Then, I eat lunch with Sami!","on_screen":"3 Revise ➕ with Sami","visual":"The words 'with Sami' slide in; Sami waves."},{"time":"01:45–02:10","narration":"Edit: Who? Action? Capital? Period? Check, check, check, check!","on_screen":"4 Edit ✔✔✔✔","visual":"Four check marks appear next to each sentence."},{"time":"02:10–02:40","narration":"Publish: Adam adds his page to our class book, 'Our School Days'.","on_screen":"5 Publish 📚","visual":"A big class book closes with many pages; the cover shows the school."}],"captions_ar":["آدم يكتب عن يومه الدراسي. لنشاهد!","التخطيط: يرسم آدم أربعة مربعات: العلوم، الرياضيات، الغداء، المنزل.","المسودة: هذا يومي الدراسي. أولًا أنظر إلى النباتات في العلوم. بعد ذلك أعدّ في الرياضيات. ثم أتناول الغداء. أخيرًا أعود إلى المنزل.","التحسين: ثم أتناول الغداء… مع سامي!","التدقيق: فاعل؟ فعل؟ حرف كبير؟ نقطة؟","النشر: يضيف آدم صفحته إلى كتاب الفصل \"أيامنا في المدرسة\"."],"voice":"Narrator: American English, warm female teacher, speed 0.8. Adam: thoughtful, clear boy voice reading his page."},"texts":[],"activities":[{"id":"RW-L01-U3-LS5-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the best answer.","instructions_ar":"اختر أفضل إجابة.","items":[{"q":"Which order word is missing? *First, I read. ___, I write. Then, I eat. Last, I go home.*","answer":"Next","explanation":"Next comes after First.","explanation_ar":"Next بعد First.","options":["First","Next","Last","Finish"],"dok":1,"skill":"order words","stage":"controlled"},{"q":"We count numbers in ___.","answer":"math","explanation":"Numbers are math.","explanation_ar":"الأرقام في الرياضيات.","options":["math","art","lunch","science"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"We paint and draw in ___.","answer":"art","explanation":"Painting is art.","explanation_ar":"الرسم في الفنية.","options":["math","science","lunch","art"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"We look at plants and animals in ___.","answer":"science","explanation":"Plants and animals are science.","explanation_ar":"النباتات في العلوم.","options":["art","math","science","home"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"At the end of the school day, we ___.","answer":"go home","explanation":"The day ends and we go home.","explanation_ar":"نعود إلى المنزل.","options":["go home","wake up","eat breakfast","start school"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Which sentence has a who, an action word and an order word?","answer":"Then, I play in the playground.","explanation":"Then + I + play.","explanation_ar":"فيها كلمة ترتيب وفاعل وفعل.","options":["Then, in the playground.","I in the playground.","Then play.","Then, I play in the playground."],"dok":2,"skill":"sentence check","stage":"controlled"}]},{"id":"RW-L01-U3-LS5-A2","type":"sequence","stage":"guided","instructions":"Put in order: Put the words in order to make a sentence.","instructions_ar":"رتّب الكلمات لتكوين جملة.","items":[{"q":"Build a 'First' sentence about the morning greeting.","answer":"First, I say good morning.","explanation":"Order word, who, action.","explanation_ar":"كلمة الترتيب ثم الفاعل ثم الفعل.","stage":"guided","parts":["I","good","morning.","First,","say"],"target":["First,","I","say","good","morning."]},{"q":"Build a 'Next' sentence about math.","answer":"Next, we count in math.","explanation":"Next, we count in math.","explanation_ar":"بعد ذلك نعدّ في الرياضيات.","stage":"guided","parts":["we","count","in","math.","Next,"],"target":["Next,","we","count","in","math."]},{"q":"Build a 'Then' sentence about art.","answer":"Then, I paint in art.","explanation":"Then, I paint in art.","explanation_ar":"ثم أرسم في الفنية.","stage":"guided","parts":["paint","Then,","I","art.","in"],"target":["Then,","I","paint","in","art."]},{"q":"Build a 'Last' sentence about going home.","answer":"Last, we go home.","explanation":"Last, we go home.","explanation_ar":"أخيرًا نعود إلى المنزل.","stage":"guided","parts":["we","Last,","home.","go"],"target":["Last,","we","go","home."]},{"q":"Build the opening sentence for a school day.","answer":"This is my school day.","explanation":"Opening sentence.","explanation_ar":"الجملة الافتتاحية.","stage":"guided","parts":["This","day.","my","is","school"],"target":["This","is","my","school","day."]},{"q":"Build a sentence about finishing work.","answer":"I finish my work.","explanation":"I finish my work.","explanation_ar":"أنهي عملي.","stage":"guided","parts":["my","finish","I","work."],"target":["I","finish","my","work."]}]},{"id":"RW-L01-U3-LS5-A3","type":"open","stage":"freer","instructions":"Freer practice: Revise! Add a place or a person to make each sentence better.","instructions_ar":"حسِّن كل جملة بإضافة مكان أو شخص.","items":[{"q":"First, I read. → First, I read ______.","answer":"First, I read a story in class.","explanation":"Add what or where.","explanation_ar":"أضف ماذا أو أين.","dok":2,"skill":"revising","stage":"freer"},{"q":"Next, I play. → Next, I play ______.","answer":"Next, I play football with Badr.","explanation":"Add what or who.","explanation_ar":"أضف ماذا أو مع مَن.","dok":2,"skill":"revising","stage":"freer"},{"q":"Then, I eat. → Then, I eat ______.","answer":"Then, I eat a sandwich in the lunch room.","explanation":"Add what or where.","explanation_ar":"أضف ماذا أو أين.","dok":2,"skill":"revising","stage":"freer"},{"q":"Last, I go home. → Last, I go home ______.","answer":"Last, I go home with my brother.","explanation":"Add who or how.","explanation_ar":"أضف مع مَن أو كيف.","dok":2,"skill":"revising","stage":"freer"}]},{"id":"RW-L01-U3-LS5-A4","type":"writing","stage":"production","instructions":"Writing: Write your school day. Then edit and publish.","instructions_ar":"اكتب يومك الدراسي ثم دققه وانشره.","items":[{"q":"Write your opening sentence and your First sentence.","answer":"This is my school day. First, I say good morning to Mr. Khalid.","explanation":"Opening + First.","explanation_ar":"افتتاحية + First.","dok":1,"skill":"writing","stage":"production"},{"q":"Write your Next sentence and your Then sentence.","answer":"Next, I count in math. Then, I eat lunch with Omar.","explanation":"Next + Then.","explanation_ar":"Next + Then.","dok":2,"skill":"writing","stage":"production"},{"q":"Write your Last sentence.","answer":"Last, I go home on the bus.","explanation":"Last + who + action.","explanation_ar":"Last + فاعل + فعل.","dok":1,"skill":"writing","stage":"production"},{"q":"Read your page to a partner. Which sentence did your partner like best?","answer":"He liked 'Then, I eat lunch with Omar.'","explanation":"One sentence.","explanation_ar":"جملة واحدة.","dok":2,"skill":"sharing","stage":"production","_w":{"checklist":[],"min":null,"max":null}}]},{"id":"RW-L01-U3-LS5-ORG","type":"organizer","organizer":"Four-Box Day Plan","instructions":"Organizer: Draw one picture in each box. Write the order word on top.","items":[{"q":"First","answer":"read a story"},{"q":"Next","answer":"count in math"},{"q":"Then","answer":"eat lunch with Omar"},{"q":"Last","answer":"go home"}]},{"id":"RW-L01-U3-LS5-WR","type":"writing","instructions":"Writing: Write about your school day. Write an opening sentence and 4 sentences with First, Next, Then and Last. Write about your school day. Write an opening sentence and 4 sentences with First, Next, Then and Last.","instructions_ar":"اكتب عن يومك الدراسي: جملة افتتاحية و4 جمل باستخدام First, Next, Then, Last.","prompt":"Write about your school day. Write an opening sentence and 4 sentences with First, Next, Then and Last.","checklist":["I wrote an opening sentence.","I used First, Next, Then and Last in order.","I put a comma after each order word.","Every sentence has a who and an action word.","Every sentence starts with a capital letter and ends with a period.","I added a place or a person to one sentence."],"rubric_id":"RW-RUBRIC-5T","min_words":20,"max_words":60,"organizer":"Four-Box Day Plan (First – Next – Then – Last)","items":[{"q":"Write about your school day. Write an opening sentence and 4 sentences with First, Next, Then and Last.","answer":"This is my school day. First, I read a story in class. Next, I count numbers in math. Then, I eat lunch with Omar. Last, I go home on the bus.","_w":{"checklist":["I wrote an opening sentence.","I used First, Next, Then and Last in order.","I put a comma after each order word.","Every sentence has a who and an action word.","Every sentence starts with a capital letter and ends with a period.","I added a place or a person to one sentence."],"min":20,"max":60}}]}],"game":{"name":"My Day Dice","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Day builder: a die rolls an order word; the child picks an action picture and types or says a sentence. The app builds a four-picture comic of the day; the comic plays at the end with narration.","Teams sit in a circle with the die and action cards in the middle.","A player rolls the die and picks an action card.","The player says a sentence with the order word and the action (\"Next, I paint in art.\").","Correct sentence = 1 point; the team writes it on the team sheet.","When the team has First, Next, Then and Last sentences, they read their day aloud for 3 bonus points."],"data":[]},"exit_quiz":[{"q":"Which order word comes first?","answer":"First","explanation":"First starts the order.","explanation_ar":"First أولًا.","options":["Then","Next","First","Last"],"dok":1,"skill":"order words"},{"q":"Where does the comma go?","answer":"First, I read.","explanation":"Comma right after the order word.","explanation_ar":"الفاصلة بعد كلمة الترتيب مباشرة.","options":["First I, read.","First, I read.","First I read,.",",First I read."],"dok":1,"skill":"punctuation"},{"q":"We count and add numbers in ___ class.","answer":"math","explanation":"Numbers = math.","explanation_ar":"الأرقام = الرياضيات.","options":["math","art","science","lunch"],"dok":1,"skill":"vocabulary"},{"q":"Which 'Last' sentence is correct?","answer":"Last, I go home.","explanation":"Order word + I + go.","explanation_ar":"Last, I go home.","options":["Last, I am go home.","Last, I goes home.","Last, go home.","Last, I go home."],"dok":1,"skill":"sentence check"},{"q":"Which sentence is better after revising?","answer":"Then, I play football in the playground.","explanation":"It adds what and where.","explanation_ar":"تضيف ماذا وأين.","options":["Then, I play.","Then, I play football in the playground.","Then.","Play then I."],"dok":2,"skill":"revising"},{"q":"What does *finish* mean?","answer":"come to the end","explanation":"Finish = come to the end.","explanation_ar":"finish تعني ينهي.","options":["start again","go to bed","come to the end","open a book"],"dok":1,"skill":"vocabulary"},{"q":"Adam writes: *First, I go home. Last, I say good morning.* What is wrong?","answer":"The order is wrong.","explanation":"Good morning comes first; going home comes last.","explanation_ar":"الترتيب خاطئ.","options":["The order is wrong.","The capitals are wrong.","There is no who.","The periods are wrong."],"dok":2,"skill":"sequence"},{"q":"What is a good opening sentence for this writing?","answer":"This is my school day.","explanation":"It tells the topic.","explanation_ar":"تذكر الموضوع.","options":["Last, I go home.","Next, I count.","This is my school day.","I like cats."],"dok":2,"skill":"opening"},{"q":"Which sentence uses a school subject?","answer":"In science, we look at a leaf.","explanation":"Science is a school subject.","explanation_ar":"العلوم مادة دراسية.","options":["In the kitchen, we cook.","In science, we look at a leaf.","At home, I sleep.","In the car, we sing."],"dok":2,"skill":"vocabulary"},{"q":"Which writing is in the best order?","answer":"First, I read. Next, I write. Then, I eat lunch. Last, I go home.","explanation":"The order words and the day are in order.","explanation_ar":"الكلمات والأحداث بالترتيب.","options":["Last, I read. First, I go home. Then, I write. Next, I eat.","Then, I eat. First, I write. Last, I read. Next, I go home.","Next, I go home. Then, I read. First, I eat. Last, I write.","First, I read. Next, I write. Then, I eat lunch. Last, I go home."],"dok":3,"skill":"sequence"}],"images":[{"id":"IMG-RW-L01-U3-LS5-V01","prompt":"Picture for the word 'day': a sun moving from sunrise to sunset over a school"},{"id":"IMG-RW-L01-U3-LS5-V02","prompt":"Picture for the word 'class': a group of students smiling at their desks"},{"id":"IMG-RW-L01-U3-LS5-V03","prompt":"Picture for the word 'math': a notebook with simple sums and a ruler"},{"id":"IMG-RW-L01-U3-LS5-V04","prompt":"Picture for the word 'art': a paint palette and brushes"},{"id":"IMG-RW-L01-U3-LS5-V05","prompt":"Picture for the word 'science': a magnifying glass over a leaf"},{"id":"IMG-RW-L01-U3-LS5-V06","prompt":"Picture for the word 'go home': children getting on a school bus"},{"id":"IMG-RW-L01-U3-LS5-V07","prompt":"Picture for the word 'finish': a child putting a gold star on a completed page"},{"id":"IMG-RW-L01-U3-LS5-01","prompt":"Adam holds up the class book while friends clap."},{"id":"IMG-RW-L01-U3-LS5-02","prompt":"Four boxes in a row with icons for parts of the day."},{"id":"IMG-RW-L01-U3-LS5-03","prompt":"Icons for math, art and science."}],"audio":[{"id":"AUD-RW-L01-U3-LS5-V01","script":"day. Today is a good day."},{"id":"AUD-RW-L01-U3-LS5-V02","script":"class. Our class has 25 students."},{"id":"AUD-RW-L01-U3-LS5-V03","script":"math. I count in math."},{"id":"AUD-RW-L01-U3-LS5-V04","script":"art. We paint in art."},{"id":"AUD-RW-L01-U3-LS5-V05","script":"science. We look at plants in science."},{"id":"AUD-RW-L01-U3-LS5-V06","script":"go home. We go home at one o'clock."},{"id":"AUD-RW-L01-U3-LS5-V07","script":"finish. I finish my work."},{"id":"AUD-RW-L01-U3-LS5-VID","script":"Adam writes about his school day. Let's watch! Plan: Adam draws four boxes – science, math, lunch, home. Draft: This is my school day. First, I look at plants in science. Next, I count in math. Then, I eat lunch. Last, I go home. Revise: Then, I eat lunch… Then, I eat lunch with Sami! Edit: Who? Action? Capital? Period? Check, check, check, check! Publish: Adam adds his page to our class book, 'Our School Days'."}]}],"unit_test":[{"q":"Mr. Fahad writes the date on the ___.","answer":"board","explanation":"Teachers write on the board.","explanation_ar":"يكتب على السبورة.","options":["lunch","board","playground","bag"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"A student sits at a ___ in class.","answer":"desk","explanation":"Students sit at desks.","explanation_ar":"يجلس الطالب إلى طاولته.","options":["desk","board","window","garden"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"I write with ink. I use a ___.","answer":"pen","explanation":"A pen has ink.","explanation_ar":"قلم الحبر فيه حبر.","options":["pencil","book","desk","pen"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"Please ___ to the story. Use your ears.","answer":"listen","explanation":"We use our ears to listen.","explanation_ar":"نستمع بآذاننا.","options":["draw","listen","write","eat"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"In ___, we paint pictures.","answer":"art","explanation":"We paint in art.","explanation_ar":"نرسم في الفنية.","options":["art","math","science","lunch"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"The bell rings and the lesson ___.","answer":"starts","explanation":"Start = begin.","explanation_ar":"يبدأ الدرس.","options":["sleeps","eats","starts","draws"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"Hamad does his last question. He ___ his work.","answer":"finishes","explanation":"Last question = finish.","explanation_ar":"ينهي عمله.","options":["starts","listens","finishes","opens"],"dok":2,"skill":"vocabulary in context","_part":"Part A – Words"},{"q":"At school, we ___ new words and numbers every day.","answer":"learn","explanation":"School is for learning.","explanation_ar":"نتعلم في المدرسة.","options":["sleep","cook","close","learn"],"dok":2,"skill":"vocabulary in context","_part":"Part A – Words"},{"q":"Which sentence has a who and an action word?","answer":"Layla paints a flower.","explanation":"Layla (who) + paints (action).","explanation_ar":"ليلى + ترسم.","options":["Layla paints a flower.","In the art room.","A red flower.","Paints a flower."],"dok":1,"skill":"sentences","_part":"Part D – Check the sentences"},{"q":"Choose the correct sentence about Faris.","answer":"Faris reads a book.","explanation":"One name → reads.","explanation_ar":"اسم واحد ← reads.","options":["Faris read a book.","Faris reads a book.","Faris am read a book.","Faris reading book."],"dok":1,"skill":"-s","_part":"Part D – Check the sentences"},{"q":"Which word fills the gap? *___, we eat lunch. Last, we go home.*","answer":"Then","explanation":"Then comes before Last.","explanation_ar":"Then قبل Last.","options":["Then","First","Last","Finish"],"dok":2,"skill":"order words","_part":"Part D – Check the sentences"},{"q":"A text has steps 1, 2, 3, 4 and a 'You need' line. What kind of text is it?","answer":"a how-to text","explanation":"Steps and a list = how-to.","explanation_ar":"نص إرشادي.","options":["a poem","a note","a story","a how-to text"],"dok":2,"skill":"genre","_part":"Part D – Check the sentences"},{"q":"Which sentence is punctuated correctly?","answer":"First, I wash my hands.","explanation":"Capital F, comma after First, period.","explanation_ar":"F كبيرة وفاصلة ونقطة.","options":["First I, wash my hands.","first, I wash my hands.","First, I wash my hands.","First, I wash my hands"],"dok":2,"skill":"conventions","_part":"Part D – Check the sentences"}],"unit_writing":{"task":"Write 4 sentences about your morning before school. Use First, Next, Then and Last.","model":"First, I wake up at six. Next, I wash my face. Then, I eat breakfast with my family. Last, I go to school with my father.","marks":20}});
